/* ---------------------------------- changement de mot de passe forcé ---------------------------------- */

function ForcePasswordChange({ session, onDone, onLogout }) {
  const [pwd, setPwd] = useState("");
  const [pwd2, setPwd2] = useState("");
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setError(null);
    if (pwd.length < 8) { setError("Le mot de passe doit contenir au moins 8 caractères."); return; }
    if (pwd !== pwd2) { setError("Les deux mots de passe ne correspondent pas."); return; }
    setBusy(true);
    try {
      await supaUpdatePassword(session.accessToken, pwd);
      try { await rpc("mark_password_changed", session.accessToken, {}); } catch {}
      onDone();
    } catch (e) { setError(e.message); } finally { setBusy(false); }
  }

  return (
    <div style={{
      fontFamily: "'IBM Plex Sans', sans-serif",
      minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center",
      background: `radial-gradient(circle at 18% 20%, #263070 0%, #000B53 45%, #00051F 100%)`,
      position: "relative", overflow: "hidden",
    }}>
      <style>{`@import url('${FONTS}'); .disp{font-family:'Space Grotesk',sans-serif;} * { box-sizing: border-box; } button{cursor:pointer;font-family:inherit;} input{font-family:inherit;}`}</style>
      <div style={{ position: "absolute", width: 420, height: 420, borderRadius: "50%", background: "#FDCF4F", opacity: 0.10, filter: "blur(90px)", top: -160, right: -140 }} />

      <div style={{ position: "relative", display: "flex", flexDirection: "column", alignItems: "center", gap: 24, zIndex: 1 }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
          <LogoMark size={44} />
          <div style={{ textAlign: "center" }}>
            <div className="disp" style={{ fontSize: 18, fontWeight: 700, color: "#fff" }}>Nouveau mot de passe requis</div>
            <p style={{ fontSize: 12.5, color: "#8B93A3", marginTop: 4, maxWidth: 320, lineHeight: 1.5 }}>
              Pour la sécurité de ton compte, choisis un mot de passe personnel avant de continuer.
            </p>
          </div>
        </div>

        <form onSubmit={handleSubmit} style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.08)", backdropFilter: "blur(20px)", borderRadius: 18, padding: 28, width: 340 }}>
          <label style={{ fontSize: 11, fontWeight: 600, color: "#8B93A3", textTransform: "uppercase" }}>Nouveau mot de passe</label>
          <input type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} required
            style={{ width: "100%", background: C.canvas, border: "1.5px solid transparent", borderRadius: 10, padding: "12px 14px", fontSize: 13.5, outline: "none", marginTop: 6, marginBottom: 14 }} />
          <label style={{ fontSize: 11, fontWeight: 600, color: "#8B93A3", textTransform: "uppercase" }}>Confirmer le mot de passe</label>
          <input type="password" value={pwd2} onChange={(e) => setPwd2(e.target.value)} required
            style={{ width: "100%", background: C.canvas, border: "1.5px solid transparent", borderRadius: 10, padding: "12px 14px", fontSize: 13.5, outline: "none", marginTop: 6, marginBottom: 18 }} />

          {error && (
            <div className="flex items-center gap-2 mb-4" style={{ background: "rgba(198,73,63,0.15)", color: "#E8938C", borderRadius: 9, padding: "9px 11px", fontSize: 12 }}>
              <AlertTriangle size={13} /> {error}
            </div>
          )}

          <button type="submit" disabled={busy}
            style={{ width: "100%", background: "#FDCF4F", color: "#00051F", border: "none", borderRadius: 10, padding: "12px 0", fontSize: 13.5, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
            {busy && <Loader2 size={14} className="animate-spin" />} Valider et continuer
          </button>
        </form>

        <button onClick={onLogout} style={{ background: "none", border: "none", color: "#8B93A3", fontSize: 12 }}>
          Se déconnecter
        </button>
      </div>
    </div>
  );
}

