function useElapsed(since) {
  const [, tick] = useState(0);
  useEffect(() => { const t = setInterval(() => tick((n) => n + 1), 1000); return () => clearInterval(t); }, []);
  const s = Math.floor((Date.now() - since) / 1000);
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
}

const ROLE_DEFAULT_TABS = {
  super_admin: ["dashboard", "resultats", "queue", "recherche", "presence", "export", "import", "campagnes", "equipes", "utilisateurs", "rules"],
  admin: ["dashboard", "resultats", "queue", "recherche", "presence", "export", "import", "campagnes", "utilisateurs", "rules"],
  superviseur: ["dashboard", "resultats", "queue", "recherche", "presence", "export"],
  coach: ["poste", "dashboard", "resultats", "export"],
  agent: ["poste", "resultats"],
};
const TAB_DEFS = [
  { id: "poste", label: "Poste de travail", icon: Inbox },
  { id: "dashboard", label: "Tableau de bord", icon: LayoutDashboard },
  { id: "resultats", label: "Mes résultats", icon: Award },
  { id: "queue", label: "File d'attente", icon: Users },
  { id: "recherche", label: "Recherche", icon: Search },
  { id: "presence", label: "Présence", icon: Timer },
  { id: "export", label: "Export", icon: FileSpreadsheet },
  { id: "import", label: "Import", icon: Upload },
  { id: "campagnes", label: "Campagnes", icon: Megaphone },
  { id: "equipes", label: "Équipes", icon: UsersRound },
  { id: "utilisateurs", label: "Utilisateurs", icon: UserCircle2 },
  { id: "rules", label: "Règles de qualification", icon: ListChecks },
];

function Workspace({ session, onLogout, onProfilChange }) {
  const { accessToken, profil, connectedAt } = session;
  const isSuperAdmin = profil?.role === "super_admin";
  const isAdmin = profil?.role === "admin" || isSuperAdmin;
  const isSuperviseur = profil?.role === "superviseur";
  const isCoach = profil?.role === "coach";
  const [role, setRole] = useState(isAdmin ? "admin" : isSuperviseur ? "superviseur" : isCoach ? "coach" : "agent");
  const [adminTab, setAdminTab] = useState((ROLE_DEFAULT_TABS[profil?.role] || ["dashboard"])[0]);
  const [tree, setTree] = useState([]);
  const elapsed = useElapsed(connectedAt);
  const [statutBusy, setStatutBusy] = useState(false);
  const [pauseTypes, setPauseTypes] = useState([]);
  const [showPauseMenu, setShowPauseMenu] = useState(false);
  const [currentPauseTypeId, setCurrentPauseTypeId] = useState(null);
  const [presenceBump, setPresenceBump] = useState(0);
  const [visibleTabs, setVisibleTabs] = useState(new Set(ROLE_DEFAULT_TABS[profil?.role] || []));

  useEffect(() => {
    (async () => {
      try {
        const pts = await supaRest("pause_types?select=*&actif=eq.true&order=ordre.asc", { accessToken });
        setPauseTypes(pts);
      } catch {}
      try {
        const open = await supaRest(`pause_details?select=pause_type_id&agent_id=eq.${session.user.id}&fin=is.null&order=debut.desc&limit=1`, { accessToken });
        if (open[0]) setCurrentPauseTypeId(open[0].pause_type_id);
      } catch {}
      if (isSuperviseur || (isAdmin && !isSuperAdmin) || isCoach) {
        try {
          const overrides = await supaRest(`permissions_personnalisees?select=ecran,autorise&profil_id=eq.${session.user.id}`, { accessToken });
          const base = new Set(ROLE_DEFAULT_TABS[profil?.role] || []);
          overrides.forEach((o) => { if (o.autorise) base.add(o.ecran); else base.delete(o.ecran); });
          setVisibleTabs(base);
        } catch {}
      }
    })();
  }, [accessToken]); // eslint-disable-line

  async function changeStatut(statut, pauseTypeId = null) {
    setStatutBusy(true);
    try {
      const p = await rpc("set_my_status", accessToken, { p_statut: statut });
      onProfilChange(p);
      if (statut === "en_pause") {
        if (currentPauseTypeId) {
          try { await supaRest(`pause_details?agent_id=eq.${session.user.id}&fin=is.null`, { method: "PATCH", accessToken, body: { fin: new Date().toISOString() } }); } catch {}
        }
        try { await supaRest("pause_details", { method: "POST", accessToken, body: { agent_id: session.user.id, pause_type_id: pauseTypeId } }); } catch {}
        setCurrentPauseTypeId(pauseTypeId);
      } else if (currentPauseTypeId) {
        try { await supaRest(`pause_details?agent_id=eq.${session.user.id}&fin=is.null`, { method: "PATCH", accessToken, body: { fin: new Date().toISOString() } }); } catch {}
        setCurrentPauseTypeId(null);
      }
    } catch {} finally { setStatutBusy(false); setShowPauseMenu(false); setPresenceBump((n) => n + 1); }
  }
  const [treeLoading, setTreeLoading] = useState(true);
  const [treeError, setTreeError] = useState(null);
  const [refreshFlag, setRefreshFlag] = useState(0);
  const bump = () => setRefreshFlag((n) => n + 1);

  const loadTree = useCallback(async () => {
    setTreeLoading(true); setTreeError(null);
    try {
      const rows = await supaRest("types_qualification?select=*&actif=eq.true&order=ordre.asc", { accessToken });
      const byCat = [];
      for (const r of rows) {
        let cat = byCat.find((c) => c.categorie === r.categorie);
        if (!cat) {
          const style = CATEGORY_STYLE[r.categorie] || FALLBACK_STYLE;
          cat = { categorie: r.categorie, ...style, subs: [] };
          byCat.push(cat);
        }
        cat.subs.push(r);
      }
      setTree(byCat);
    } catch (e) {
      setTreeError(e.message);
    } finally {
      setTreeLoading(false);
    }
  }, [accessToken]);

  useEffect(() => { loadTree(); }, [loadTree]);

  // En mode "aperçu agent" (bascule Admin/Superviseur → Agent), on affiche
  // toujours exactement ce qu'un agent voit par défaut — pas les permissions
  // réelles du compte connecté, qui resteraient sinon visibles en aperçu.
  const effectiveTabs = role === "agent" ? new Set(ROLE_DEFAULT_TABS.agent) : visibleTabs;

  return (
    <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", background: C.canvas, color: C.text, minHeight: "100vh" }}>
      <style>{`@import url('${FONTS}');
        .disp { font-family: 'Space Grotesk', sans-serif; } .mono { font-family: 'IBM Plex Mono', monospace; }
        * { box-sizing: border-box; } button { font-family: inherit; cursor: pointer; } input, textarea { font-family: inherit; }
        @keyframes spin { to { transform: rotate(360deg); } } .animate-spin { animation: spin 1s linear infinite; }
      `}</style>

      <div className="flex" style={{ minHeight: "100vh" }}>
        <aside style={{ width: 232, background: C.ink, color: "#fff", flexShrink: 0 }} className="flex flex-col justify-between">
          <div>
            <div className="px-5 pt-6 pb-5" style={{ borderBottom: `1px solid ${C.inkFaint}` }}>
              <div className="flex items-center gap-2">
                <div style={{ width: 26, height: 26, borderRadius: 7, background: C.amber }} className="flex items-center justify-center">
                  <ArrowRight size={15} color={C.ink} strokeWidth={2.5} />
                </div>
                <span className="disp" style={{ fontSize: 19, fontWeight: 700 }}>Auréo</span>
              </div>
              <p style={{ fontSize: 11.5, color: "#8B93A3", marginTop: 6, lineHeight: 1.4 }}>Connecté à Supabase en direct.</p>
            </div>

            {isAdmin && (
              <div className="px-5 pt-4">
                <div style={{ background: C.inkSoft, borderRadius: 10, padding: 4 }} className="flex gap-1">
                  {["agent", "admin"].map((r) => (
                    <button key={r} onClick={() => { setRole(r); setAdminTab(r === "agent" ? "poste" : (ROLE_DEFAULT_TABS[profil?.role] || ["dashboard"])[0]); }}
                      style={{ flex: 1, padding: "7px 0", borderRadius: 7, border: "none", background: role === r ? C.amber : "transparent", color: role === r ? C.ink : "#A6ADBA", fontSize: 12.5, fontWeight: 600 }}>
                      {r === "agent" ? "Agent" : "Admin"}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <nav className="px-3 pt-5 flex flex-col gap-1">
              {TAB_DEFS.filter((t) => effectiveTabs.has(t.id)).map((t) => (
                <NavItem key={t.id} icon={t.icon} label={t.label} active={adminTab === t.id} onClick={() => setAdminTab(t.id)} />
              ))}
            </nav>
          </div>

          <div className="px-5 py-4" style={{ borderTop: `1px solid ${C.inkFaint}` }}>
            <div className="flex items-center gap-2 mb-3.5">
              <LogoMark size={22} />
              <span className="disp" style={{ fontSize: 13.5, fontWeight: 700, color: "#fff" }}>Auréo</span>
            </div>
            <div className="flex items-center gap-2.5 mb-2.5">
              <div style={{ width: 30, height: 30, borderRadius: 999, background: C.inkFaint }} className="flex items-center justify-center">
                <UserCircle2 size={18} color="#A6ADBA" />
              </div>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 12.5, fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{profil?.nom || session.user.email}</div>
                <div style={{ fontSize: 10.5, color: "#8B93A3" }}>{isSuperAdmin ? "Super Administrateur" : isAdmin ? "Administrateur" : isSuperviseur ? "Superviseur" : isCoach ? "Coach" : "Agent"}</div>
              </div>
            </div>
            <div className="flex items-center gap-1.5 mono mb-3" style={{ fontSize: 11.5, color: C.amber, background: "rgba(224,147,43,0.12)", borderRadius: 7, padding: "5px 9px" }}>
              <Timer size={12} /> {elapsed}
            </div>

            <div style={{ position: "relative" }}>
              <div style={{ background: C.inkSoft, borderRadius: 9, padding: 4 }} className="flex gap-1 mb-3">
                {AGENT_STATUTS.map((st) => {
                  const Icon = st.icon;
                  const active = profil?.statut === st.id;
                  return (
                    <button key={st.id} disabled={statutBusy} title={st.label}
                      onClick={() => { st.id === "en_pause" ? setShowPauseMenu((v) => !v) : (setShowPauseMenu(false), changeStatut(st.id)); }}
                      style={{ flex: 1, padding: "6px 0", borderRadius: 6, border: "none", background: active ? st.color : "transparent", display: "flex", alignItems: "center", justifyContent: "center" }}>
                      <Icon size={14} color={active ? C.ink : "#8B93A3"} />
                    </button>
                  );
                })}
              </div>

              {showPauseMenu && (
                <div style={{ position: "absolute", bottom: "100%", left: 0, right: 0, marginBottom: 8, background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10, padding: 5, boxShadow: "0 12px 30px rgba(0,0,0,0.3)", zIndex: 30 }}>
                  {pauseTypes.length === 0 ? (
                    <div style={{ padding: "8px 9px", fontSize: 11.5, color: C.mutedSoft }}>Aucun type de pause configuré.</div>
                  ) : pauseTypes.map((pt) => (
                    <button key={pt.id} onClick={() => changeStatut("en_pause", pt.id)}
                      style={{ width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: 8, padding: "7px 9px", borderRadius: 6, border: "none", background: currentPauseTypeId === pt.id && profil?.statut === "en_pause" ? C.canvas : "transparent", fontSize: 12, fontWeight: 500, color: C.text }}>
                      <span style={{ width: 8, height: 8, borderRadius: 999, background: pt.couleur, flexShrink: 0 }} />
                      {pt.nom}
                    </button>
                  ))}
                </div>
              )}
            </div>
            <div style={{ fontSize: 10, color: "#8B93A3", textAlign: "center", marginBottom: 10 }}>
              {profil?.statut === "en_pause" && currentPauseTypeId
                ? (pauseTypes.find((pt) => pt.id === currentPauseTypeId)?.nom || "Pause")
                : (AGENT_STATUTS.find((s) => s.id === profil?.statut)?.label || "—")}
            </div>

            <button onClick={onLogout} className="flex items-center gap-1.5" style={{ background: "none", border: "none", color: "#8B93A3", fontSize: 11.5 }}>
              <LogOut size={13} /> Se déconnecter
            </button>
          </div>
        </aside>

        <main className="flex-1" style={{ padding: "32px 40px", maxWidth: 1180 }}>
          {treeLoading ? (
            <CenterLoader />
          ) : treeError ? (
            <ErrorBlock message={treeError} />
          ) : (
            <>
              {adminTab === "poste" && effectiveTabs.has("poste") && <AgentView accessToken={accessToken} tree={tree} refreshFlag={refreshFlag} bump={bump} agentId={session.user.id} statut={profil?.statut} pauseTypeId={currentPauseTypeId} presenceBump={presenceBump} />}
              {adminTab === "dashboard" && effectiveTabs.has("dashboard") && <Dashboard accessToken={accessToken} refreshFlag={refreshFlag} callerRole={profil?.role} />}
              {adminTab === "resultats" && effectiveTabs.has("resultats") && <MesResultatsPanel accessToken={accessToken} />}
              {adminTab === "queue" && effectiveTabs.has("queue") && <Queue accessToken={accessToken} refreshFlag={refreshFlag} bump={bump} />}
              {adminTab === "recherche" && effectiveTabs.has("recherche") && <SearchPanel accessToken={accessToken} tree={tree} isAdmin={isAdmin} />}
              {adminTab === "presence" && effectiveTabs.has("presence") && <PresencePanel accessToken={accessToken} />}
              {adminTab === "export" && effectiveTabs.has("export") && <ExportPanel accessToken={accessToken} />}
              {adminTab === "import" && effectiveTabs.has("import") && <ImportPanel accessToken={accessToken} bump={bump} />}
              {adminTab === "campagnes" && effectiveTabs.has("campagnes") && <CampaignsPanel accessToken={accessToken} />}
              {adminTab === "equipes" && effectiveTabs.has("equipes") && <EquipesPanel accessToken={accessToken} />}
              {adminTab === "utilisateurs" && effectiveTabs.has("utilisateurs") && <UsersPanel accessToken={accessToken} isSuperAdmin={isSuperAdmin} />}
              {adminTab === "rules" && effectiveTabs.has("rules") && <Rules accessToken={accessToken} tree={tree} reload={loadTree} />}
            </>
          )}
        </main>
      </div>
    </div>
  );
}

function CenterLoader() {
  return (
    <div className="flex items-center gap-2" style={{ color: C.muted, fontSize: 13, padding: 40 }}>
      <Loader2 size={16} className="animate-spin" /> Chargement…
    </div>
  );
}
function ErrorBlock({ message }) {
  return (
    <div className="flex items-center gap-2" style={{ background: C.redSoft, color: C.red, borderRadius: 9, padding: "12px 16px", fontSize: 13, maxWidth: 520 }}>
      <AlertTriangle size={15} /> {message}
    </div>
  );
}

function NavItem({ icon: Icon, label, active, onClick }) {
  return (
    <button onClick={onClick} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 12px", borderRadius: 8, border: "none", background: active ? C.inkSoft : "transparent", color: active ? "#fff" : "#9AA1B0", fontSize: 13, fontWeight: 500, textAlign: "left" }}>
      <Icon size={16} strokeWidth={2} /> {label}
    </button>
  );
}

/* ---------------------------------- vue agent ---------------------------------- */

function AgentView({ accessToken, tree, bump, agentId, statut, pauseTypeId, presenceBump }) {
  const [view, setView] = useState("poste"); // poste | recherche
  const [fiche, setFiche] = useState(null);
  const [pulling, setPulling] = useState(false);
  const ficheStartRef = useRef(null);
  const [, ficheTick] = useState(0);
  useEffect(() => { const t = setInterval(() => ficheTick((n) => n + 1), 1000); return () => clearInterval(t); }, []);
  const ficheElapsedStr = (() => {
    if (!ficheStartRef.current) return "00:00";
    const s = Math.floor((Date.now() - ficheStartRef.current) / 1000);
    const m = Math.floor(s / 60), sec = s % 60;
    return `${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
  })();
  const [cat, setCat] = useState(null);
  const [sub, setSub] = useState(null);
  const [orphelines, setOrphelines] = useState([]);
  const [sidebarBump, setSidebarBump] = useState(0);
  const [showOrphelines, setShowOrphelines] = useState(false);
  const [rappelDate, setRappelDate] = useState("");
  const [rappelHeure, setRappelHeure] = useState("");
  const [dateValidation, setDateValidation] = useState("");
  const [note, setNote] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [lastOutcome, setLastOutcome] = useState(null);
  const [error, setError] = useState(null);
  const [lastQualif, setLastQualif] = useState(null);
  const [stats, setStats] = useState({ fiches: 0, rappels: 0, ventes: 0 });
  const [myPresence, setMyPresence] = useState(null);
  const [, forceTick] = useState(0);

  useEffect(() => {
    const t = setInterval(() => forceTick((n) => n + 1), 1000);
    return () => clearInterval(t);
  }, []);

  const loadMyPresence = useCallback(async () => {
    try {
      const todayStr = new Date().toISOString().slice(0, 10);
      const startOfDay = new Date(todayStr + "T00:00:00");
      const [tempsRows, pauseTypes, pauseDetails] = await Promise.all([
        supaRest(`vue_temps_agent_jour?select=statut,secondes&agent_id=eq.${agentId}&jour=eq.${todayStr}`, { accessToken }),
        supaRest("pause_types?select=*&actif=eq.true&order=ordre.asc", { accessToken }),
        supaRest(`pause_details?select=pause_type_id,debut,fin&agent_id=eq.${agentId}&debut=gte.${startOfDay.toISOString()}`, { accessToken }),
      ]);
      const enProd = tempsRows.find((t) => t.statut === "en_prod")?.secondes || 0;
      const now = Date.now();
      const byType = {};
      for (const d of pauseDetails) {
        const pt = pauseTypes.find((t) => t.id === d.pause_type_id);
        if (!pt) continue;
        const finMs = d.fin ? new Date(d.fin).getTime() : now;
        const seconds = Math.max(0, (finMs - new Date(d.debut).getTime()) / 1000);
        if (!byType[pt.code]) byType[pt.code] = { ...pt, seconds: 0, occurrences: 0 };
        byType[pt.code].seconds += seconds;
        byType[pt.code].occurrences += 1;
      }
      setMyPresence({ enProd, byType, fetchedAt: now, pauseTypesOrder: pauseTypes.map((t) => t.code) });
    } catch {}
  }, [accessToken, agentId]);

  useEffect(() => {
    loadMyPresence();
    const t = setInterval(loadMyPresence, 30000);
    return () => clearInterval(t);
  }, [loadMyPresence, presenceBump]);

  const loadStats = useCallback(async () => {
    try {
      const startOfDay = new Date(); startOfDay.setHours(0, 0, 0, 0);
      const rows = await supaRest(
        `qualifications?select=types_qualification(categorie,est_vente)&agent_id=eq.${agentId}&created_at=gte.${startOfDay.toISOString()}`,
        { accessToken }
      );
      setStats({
        fiches: rows.length,
        rappels: rows.filter((r) => r.types_qualification?.categorie === "À rappeler").length,
        ventes: rows.filter((r) => r.types_qualification?.est_vente).length,
      });
    } catch {}
  }, [accessToken, agentId]);

  useEffect(() => { loadStats(); }, [loadStats]);

  // Fiches "en cours" sous ce compte mais jamais qualifiées (bug, mauvaise
  // manip, fermeture d'onglet en plein appel...). Comme l'app ne garde
  // jamais qu'une seule fiche ouverte à la fois, toute fiche "en_cours" hors
  // de celle actuellement affichée est forcément un reliquat oublié.
  const loadOrphelines = useCallback(async () => {
    try {
      const rows = await supaRest(
        `clients?select=id,nom,telephone,numero_fiche,numero_box,updated_at&statut=eq.en_cours&agent_id=eq.${agentId}&order=updated_at.asc`,
        { accessToken }
      );
      setOrphelines(rows);
    } catch {}
  }, [accessToken, agentId]);

  useEffect(() => { loadOrphelines(); const t = setInterval(loadOrphelines, 30000); return () => clearInterval(t); }, [loadOrphelines]);

  const [showCreateClient, setShowCreateClient] = useState(false);

  async function openFicheDirect(f) {
    setFiche(f);
    ficheStartRef.current = f ? Date.now() : null;
    setCat(null); setSub(null); setNote(""); setLastOutcome(null); setLastQualif(null);
    setView("poste");
    if (f) {
      try {
        const hist = await supaRest(
          `qualifications?select=commentaire,created_at,types_qualification(categorie,motif)&client_id=eq.${f.id}&order=created_at.desc&limit=1`,
          { accessToken }
        );
        setLastQualif(hist[0] || null);
      } catch {}
    }
    loadOrphelines();
  }

  async function pullNext() {
    setPulling(true); setError(null); setLastOutcome(null); setLastQualif(null);
    try {
      const result = await rpc("get_next_fiche", accessToken, {});
      const f = result && result.id ? result : null;
      setFiche(f);
      ficheStartRef.current = f ? Date.now() : null;
      setCat(null); setSub(null); setNote("");
      if (f) {
        try {
          const hist = await supaRest(
            `qualifications?select=commentaire,created_at,types_qualification(categorie,motif)&client_id=eq.${f.id}&order=created_at.desc&limit=1`,
            { accessToken }
          );
          setLastQualif(hist[0] || null);
        } catch {}
      }
    } catch (e) { setError(e.message); } finally { setPulling(false); }
  }

  async function handleValidate() {
    const catObj = tree.find((t) => t.categorie === cat);
    const subObj = catObj.subs.find((s) => s.id === sub);
    const dureeSecondes = ficheStartRef.current ? Math.round((Date.now() - ficheStartRef.current) / 1000) : null;
    const visibleApres = cat === "À rappeler" && rappelDate && rappelHeure
      ? new Date(`${rappelDate}T${rappelHeure}`).toISOString()
      : null;
    const commentaireFinal = (subObj.motif === "Rechargement validé" && dateValidation)
      ? `Date de validation : ${new Date(dateValidation + "T00:00:00").toLocaleDateString("fr-FR")}${note ? " — " + note : ""}`
      : (note || null);
    setSubmitting(true); setError(null);
    try {
      await rpc("qualifier_fiche", accessToken, {
        p_client_id: fiche.id, p_type_qualification_id: subObj.id, p_commentaire: commentaireFinal,
        p_duree_secondes: dureeSecondes, p_visible_apres: visibleApres,
      });
      setLastOutcome({ cat: catObj, sub: subObj });
      setFiche(null);
      ficheStartRef.current = null;
      setRappelDate(""); setRappelHeure(""); setDateValidation("");
      bump();
      loadStats();
      loadOrphelines();
      setTimeout(loadOrphelines, 1500);
      setSidebarBump((n) => n + 1);
    } catch (e) { setError(e.message); } finally { setSubmitting(false); }
  }

  const today = new Date().toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" });

  return (
    <div>
      <header className="mb-5 flex items-start justify-between">
        <div>
          <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>{view === "recherche" ? "Recherche" : "Poste de travail"}</h1>
          <p style={{ fontSize: 13, color: C.muted, marginTop: 3, textTransform: view === "recherche" ? "none" : "capitalize" }}>
            {view === "recherche" ? "Par numéro de box, nom du client ou téléphone." : today}
          </p>
        </div>

        <div className="flex flex-col items-end gap-3">
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10, padding: 4 }} className="flex gap-1">
            <button onClick={() => setView("poste")}
              style={{ display: "flex", alignItems: "center", gap: 6, padding: "7px 13px", borderRadius: 7, border: "none", background: view === "poste" ? C.ink : "transparent", color: view === "poste" ? "#fff" : C.muted, fontSize: 12.5, fontWeight: 600 }}>
              <Inbox size={13} /> Poste de travail
            </button>
            <button onClick={() => setView("recherche")}
              style={{ display: "flex", alignItems: "center", gap: 6, padding: "7px 13px", borderRadius: 7, border: "none", background: view === "recherche" ? C.ink : "transparent", color: view === "recherche" ? "#fff" : C.muted, fontSize: 12.5, fontWeight: 600 }}>
              <Search size={13} /> Recherche
            </button>
          </div>

          {view === "poste" && (
            <div className="flex items-center gap-4">
              <div style={{ textAlign: "right" }}>
                <div className="disp mono" style={{ fontSize: 20, fontWeight: 700 }}>{stats.fiches}</div>
                <div style={{ fontSize: 10.5, color: C.muted }}>fiches traitées</div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div className="disp mono" style={{ fontSize: 20, fontWeight: 700, color: C.amber }}>{stats.rappels}</div>
                <div style={{ fontSize: 10.5, color: C.muted }}>rappels traités</div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div className="disp mono" style={{ fontSize: 20, fontWeight: 700, color: C.green }}>{stats.ventes}</div>
                <div style={{ fontSize: 10.5, color: C.muted }}>ventes</div>
              </div>
            </div>
          )}
        </div>
      </header>

      {view === "poste" && myPresence && (() => {
        const elapsedSinceFetch = Math.max(0, (Date.now() - myPresence.fetchedAt) / 1000);
        const liveEnProd = myPresence.enProd + (statut === "en_prod" ? elapsedSinceFetch : 0);
        const liveByType = {};
        for (const code of myPresence.pauseTypesOrder || []) {
          const t = myPresence.byType[code];
          const base = t?.seconds || 0;
          const isActive = statut === "en_pause" && t?.id === pauseTypeId;
          liveByType[code] = { ...t, seconds: base + (isActive ? elapsedSinceFetch : 0) };
        }
        let presenceBrute = liveEnProd, occupationImpact = 0;
        Object.values(liveByType).forEach((t) => {
          if (t.compte_presence) presenceBrute += t.seconds;
          if (t.compte_occupation) occupationImpact += t.seconds;
        });
        const liveOccupation = (liveEnProd + occupationImpact) > 0 ? liveEnProd / (liveEnProd + occupationImpact) : null;

        return (
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: "14px 18px", marginBottom: 18, display: "flex", alignItems: "center", gap: 26, flexWrap: "wrap" }}>
            <div>
              <div style={{ fontSize: 9.5, color: C.mutedSoft, textTransform: "uppercase", letterSpacing: "0.03em" }}>Production (jour)</div>
              <div className="mono" style={{ fontSize: 15, fontWeight: 700, marginTop: 2 }}>{fmtDuration(liveEnProd)}</div>
            </div>
            <div>
              <div style={{ fontSize: 9.5, color: C.mutedSoft, textTransform: "uppercase", letterSpacing: "0.03em" }}>Occupation</div>
              <div className="mono" style={{ fontSize: 15, fontWeight: 700, marginTop: 2, color: liveOccupation === null ? C.mutedSoft : liveOccupation >= 0.8 ? C.green : liveOccupation >= 0.5 ? C.amber : C.red }}>
                {liveOccupation === null ? "—" : `${Math.round(liveOccupation * 100)}%`}
              </div>
            </div>
            <div style={{ width: 1, height: 30, background: C.borderSoft }} />
            {(myPresence.pauseTypesOrder || []).map((code) => {
              const t = liveByType[code];
              const seconds = t?.seconds || 0;
              const capMin = t?.duree_max_minutes && t?.occurrences_max_jour ? t.duree_max_minutes * t.occurrences_max_jour : null;
              const overCap = capMin && seconds / 60 > capMin;
              const isActive = statut === "en_pause" && t?.id === pauseTypeId;
              return (
                <div key={code}>
                  <div style={{ fontSize: 9.5, color: C.mutedSoft, textTransform: "uppercase", letterSpacing: "0.03em" }}>{t?.nom || code}</div>
                  <div className="mono" style={{ fontSize: 14, fontWeight: 600, marginTop: 2, color: overCap ? C.red : isActive ? C.amber : C.text }}>
                    {fmtDuration(seconds)}{capMin ? ` / ${capMin}m` : ""}
                  </div>
                </div>
              );
            })}
          </div>
        );
      })()}

      {view === "recherche" ? (
        <AgentSearch accessToken={accessToken} agentId={agentId} onAfficher={openFicheDirect} />
      ) : (
      <div style={{ display: "grid", gridTemplateColumns: "1fr 320px", gap: 20, alignItems: "start" }}>
      <div>
      {error && <div className="mb-4"><ErrorBlock message={error} /></div>}

      {showCreateClient && (
        <CreateClientPanel
          accessToken={accessToken} agentId={agentId}
          onClose={() => setShowCreateClient(false)}
          onCreated={(client) => { setShowCreateClient(false); openFicheDirect(client); }}
        />
      )}

      {(() => {
        const listeOrphelines = orphelines.filter((o) => o.id !== fiche?.id);
        if (listeOrphelines.length === 0) return null;
        return (
          <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 12, marginBottom: 16, overflow: "hidden" }}>
            <button onClick={() => setShowOrphelines((v) => !v)}
              className="flex items-center justify-between" style={{ width: "100%", padding: "12px 16px", background: "none", border: "none", cursor: "pointer" }}>
              <span className="flex items-center gap-2" style={{ fontSize: 13, fontWeight: 600, color: C.ink }}>
                <AlertTriangle size={14} color={C.amber} />
                {listeOrphelines.length} fiche{listeOrphelines.length !== 1 ? "s" : ""} en cours non qualifiée{listeOrphelines.length !== 1 ? "s" : ""}
              </span>
              <span style={{ fontSize: 11.5, color: C.muted }}>{showOrphelines ? "Masquer" : "Afficher"}</span>
            </button>
            {showOrphelines && (
              <div style={{ borderTop: `1px solid ${C.amber}`, padding: "8px 12px" }}>
                <p style={{ fontSize: 11, color: C.muted, margin: "4px 4px 10px" }}>
                  Ces fiches ont été récupérées mais jamais qualifiées (bug, mauvaise manipulation, fermeture accidentelle...). Reprends-les pour les traiter.
                </p>
                {listeOrphelines.map((o) => (
                  <div key={o.id} className="flex items-center justify-between" style={{ padding: "8px 8px", borderTop: `1px solid ${C.border}` }}>
                    <div>
                      <div style={{ fontSize: 12.5, fontWeight: 500 }}>{o.nom}</div>
                      <div className="mono" style={{ fontSize: 10.5, color: C.mutedSoft }}>
                        #{o.numero_fiche} · récupérée {formatRelatif(o.updated_at)}
                      </div>
                    </div>
                    <button onClick={() => openFicheDirect(o)}
                      style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 7, padding: "6px 12px", fontSize: 12, fontWeight: 600 }}>
                      Reprendre
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      })()}

      {!fiche ? (
        <EmptyOrOutcome outcome={lastOutcome} onPull={pullNext} pulling={pulling} onCreateClient={() => setShowCreateClient(true)} />
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "340px 1fr", gap: 24 }}>
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 14, overflow: "hidden" }}>
            <div style={{ background: C.ink, color: "#fff", padding: "14px 18px" }} className="flex items-center justify-between">
              <span className="mono flex items-center gap-3" style={{ fontSize: 11, letterSpacing: "0.04em", color: "#A6ADBA" }}>
                <span className="flex items-center gap-1"><Hash size={11} />{fiche.numero_fiche}</span>
                {fiche.numero_box && <span style={{ color: "#fff", fontSize: 13, fontWeight: 600 }}>Box {fiche.numero_box}</span>}
              </span>
              <span style={{ fontSize: 10.5, background: C.amber, color: C.ink, padding: "2px 8px", borderRadius: 999, fontWeight: 600 }}>EN COURS</span>
            </div>
            <div className="mono flex items-center gap-1.5" style={{ padding: "7px 18px", background: C.canvas, borderBottom: `1px solid ${C.borderSoft}`, fontSize: 11, color: C.muted }}>
              <Clock size={11} /> {ficheElapsedStr} sur cette fiche
            </div>
            {lastQualif && (
              <div style={{ padding: "10px 18px", background: C.amberSoft, borderBottom: `1px solid ${C.amber}` }}>
                <div className="flex items-center gap-1.5" style={{ fontSize: 10.5, color: C.ink, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.02em" }}>
                  <History size={12} color={C.amber} /> Déjà contactée · {new Date(lastQualif.created_at).toLocaleDateString("fr-FR")}
                </div>
                <div style={{ fontSize: 12.5, fontWeight: 600, marginTop: 2 }}>
                  {lastQualif.types_qualification?.categorie} · {lastQualif.types_qualification?.motif}
                </div>
                {lastQualif.commentaire && (
                  <p style={{ fontSize: 11.5, color: C.muted, marginTop: 3, lineHeight: 1.4, fontStyle: "italic" }}>« {lastQualif.commentaire} »</p>
                )}
              </div>
            )}
            <div className="px-5 py-5">
              <h2 className="disp" style={{ fontSize: 19, fontWeight: 700 }}>{fiche.nom}</h2>
              <div style={{ height: 1, background: C.borderSoft, margin: "16px 0" }} />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
                <FicheField label="Numéro de contact 1" value={fiche.telephone} icon={Phone} mono />
                <FicheField label="Numéro MTN" value={fiche.numero_mtn} icon={Phone} mono />
                <FicheField label="Type de segment" value={fiche.segment} icon={CircleDot} />
                <FicheField label="Commune" value={fiche.commune} icon={Building2} />
              </div>
            </div>
          </div>

          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 14, padding: 24 }}>
            <h3 className="disp" style={{ fontSize: 15, fontWeight: 600, marginBottom: 4 }}>Qualifier cette fiche</h3>
            <p style={{ fontSize: 12, color: C.muted, marginBottom: 18 }}>Choisissez une issue, puis précisez le motif.</p>

            <div style={{ display: "grid", gridTemplateColumns: `repeat(${tree.length || 1}, 1fr)`, gap: 10 }}>
              {tree.map((c) => {
                const Icon = c.icon;
                const isActive = cat === c.categorie;
                return (
                  <button key={c.categorie} onClick={() => {
                    setCat(c.categorie);
                    setSub(c.categorie === "À rappeler" ? c.subs[0]?.id ?? null : null);
                    setRappelDate(""); setRappelHeure(""); setDateValidation("");
                  }}
                    style={{ background: isActive ? c.soft : C.surface, border: `1.5px solid ${isActive ? c.color : C.border}`, borderRadius: 10, padding: "14px 10px", display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>
                    <Icon size={18} color={c.color} />
                    <span style={{ fontSize: 12, fontWeight: 600, color: isActive ? c.color : C.text }}>{c.categorie}</span>
                  </button>
                );
              })}
            </div>

            {cat && (
              <div style={{ marginTop: 16, paddingTop: 16, borderTop: `1px dashed ${C.border}` }}>
                {cat === "À rappeler" ? (
                  <>
                    <div className="flex items-center gap-1.5 mb-3" style={{ fontSize: 11.5, color: C.mutedSoft }}>
                      <ArrowRight size={12} /> Jour et heure souhaités par le client
                    </div>
                    <div className="flex items-center gap-3">
                      <input type="date" value={rappelDate} min={new Date().toISOString().slice(0, 10)}
                        onChange={(e) => setRappelDate(e.target.value)}
                        style={{ border: `1px solid ${C.border}`, borderRadius: 8, padding: "9px 11px", fontSize: 13 }} />
                      <input type="time" value={rappelHeure} onChange={(e) => setRappelHeure(e.target.value)}
                        style={{ border: `1px solid ${C.border}`, borderRadius: 8, padding: "9px 11px", fontSize: 13 }} />
                    </div>
                  </>
                ) : (
                  <>
                    <div className="flex items-center gap-1.5 mb-3" style={{ fontSize: 11.5, color: C.mutedSoft }}><ArrowRight size={12} /> Motif précis</div>
                    <div className="flex flex-wrap gap-2">
                      {tree.find((t) => t.categorie === cat).subs.map((s) => {
                        const isActive = sub === s.id;
                        const catColor = tree.find((t) => t.categorie === cat).color;
                        return (
                          <button key={s.id} onClick={() => setSub(s.id)}
                            style={{ border: `1.5px solid ${isActive ? catColor : C.border}`, background: isActive ? catColor : C.surface, color: isActive ? "#fff" : C.text, borderRadius: 999, padding: "7px 14px", fontSize: 12.5, fontWeight: 500 }}>
                            {s.motif}
                            {!s.terminale && <span style={{ opacity: isActive ? 0.85 : 0.55, marginLeft: 6, fontSize: 11 }}>· {s.delai_heures < 24 ? `${s.delai_heures}h` : `${Math.round(s.delai_heures / 24)}j`}</span>}
                          </button>
                        );
                      })}
                    </div>
                    {(() => {
                      const motifActif = tree.find((t) => t.categorie === cat).subs.find((s) => s.id === sub);
                      if (motifActif?.motif !== "Rechargement validé") return null;
                      return (
                        <div style={{ marginTop: 12 }}>
                          <div className="flex items-center gap-1.5 mb-2" style={{ fontSize: 11, color: C.mutedSoft }}>
                            <ArrowRight size={11} /> Date de validation du rechargement
                          </div>
                          <input type="date" value={dateValidation} onChange={(e) => setDateValidation(e.target.value)}
                            style={{ border: `1px solid ${C.border}`, borderRadius: 8, padding: "8px 11px", fontSize: 13 }} />
                          <span style={{ fontSize: 10.5, color: C.mutedSoft, marginLeft: 8 }}>Les dates passées sont acceptées.</span>
                        </div>
                      );
                    })()}
                  </>
                )}
              </div>
            )}

            {sub && (cat !== "À rappeler" || (rappelDate && rappelHeure)) && (
              <div style={{ marginTop: 18, paddingTop: 18, borderTop: `1px dashed ${C.border}` }}>
                <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Commentaire (facultatif)…" rows={2}
                  style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 8, padding: "9px 11px", fontSize: 12.5, resize: "none", outline: "none" }} />
                <div className="flex items-center justify-between mt-3">
                  {(() => {
                    if (cat === "À rappeler") {
                      const d = new Date(`${rappelDate}T${rappelHeure}`);
                      return (
                        <span style={{ fontSize: 11.5, color: C.mutedSoft }}>
                          → Rappel programmé le {d.toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" })} à {rappelHeure}.
                        </span>
                      );
                    }
                    const s = tree.find((t) => t.categorie === cat).subs.find((x) => x.id === sub);
                    return (
                      <span style={{ fontSize: 11.5, color: C.mutedSoft }}>
                        {s.terminale ? "→ Fiche archivée, ne réapparaît plus." : `→ Revient dans la file dans ${s.delai_heures < 24 ? `${s.delai_heures}h` : `${Math.round(s.delai_heures / 24)} jour(s)`}.`}
                      </span>
                    );
                  })()}
                  <button onClick={handleValidate} disabled={submitting}
                    style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 8, padding: "9px 18px", fontSize: 13, fontWeight: 600, display: "flex", alignItems: "center", gap: 8 }}>
                    {submitting && <Loader2 size={13} className="animate-spin" />} Valider la qualification
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
      </div>
      <AgentSidebar accessToken={accessToken} agentId={agentId} refreshTrigger={sidebarBump} />
      </div>
      )}
    </div>
  );
}

function AgentSidebar({ accessToken, agentId, refreshTrigger }) {
  const [rappels, setRappels] = useState(null);
  const [error, setError] = useState(null);
  const [showTraitees, setShowTraitees] = useState(false);
  const [showRappels, setShowRappels] = useState(false);
  const [traitees, setTraitees] = useState(null);

  const loadRappels = useCallback(async () => {
    try {
      const now = new Date();
      const jour = (now.getDay() + 6) % 7; // lundi = 0
      const debut = new Date(now.getFullYear(), now.getMonth(), now.getDate() - jour);
      const fin = new Date(debut.getTime() + 7 * 24 * 3600 * 1000);
      // !inner + filtre sur la catégorie embarquée : ne remonte que les
      // fiches dont le motif appartient à "À rappeler" — pas n'importe
      // quelle qualification non-terminale (ex. "Rechargement validé", qui
      // revient aussi dans la file mais n'est pas un rappel demandé).
      const rows = await supaRest(
        `clients?select=id,nom,telephone,numero_fiche,visible_apres,types_qualification!inner(categorie)&statut=eq.planifie&agent_id=eq.${agentId}&types_qualification.categorie=eq.${encodeURIComponent("À rappeler")}&visible_apres=gte.${debut.toISOString()}&visible_apres=lt.${fin.toISOString()}&order=visible_apres.asc`,
        { accessToken }
      );
      setRappels(rows);
    } catch (e) { setError(e.message); }
  }, [accessToken, agentId]);

  useEffect(() => { loadRappels(); const t = setInterval(loadRappels, 30000); return () => clearInterval(t); }, [loadRappels]);
  // Rafraîchissement immédiat dès qu'une qualification vient d'être validée
  // (sans attendre le prochain cycle de 30s) — évite qu'un rappel tout juste
  // traité reste visible dans la liste pendant jusqu'à 30 secondes.
  // Un second rafraîchissement, décalé d'1,5s, sert de filet de sécurité au
  // cas où la lecture immédiate arriverait avant que l'écriture ne soit
  // pleinement visible côté base.
  useEffect(() => {
    if (!refreshTrigger) return;
    loadRappels();
    const t = setTimeout(loadRappels, 1500);
    return () => clearTimeout(t);
  }, [refreshTrigger]); // eslint-disable-line

  const fetchTraitees = useCallback(async () => {
    try {
      const startOfDay = new Date(); startOfDay.setHours(0, 0, 0, 0);
      const rows = await supaRest(
        `qualifications?select=created_at,commentaire,types_qualification(categorie,motif),clients(nom,numero_fiche)&agent_id=eq.${agentId}&created_at=gte.${startOfDay.toISOString()}&order=created_at.desc`,
        { accessToken }
      );
      setTraitees(rows);
    } catch { setTraitees([]); }
  }, [accessToken, agentId]);

  async function loadTraitees() {
    if (traitees === null) await fetchTraitees();
    setShowTraitees((v) => !v);
  }

  // Si la liste est déjà ouverte, la rafraîchir dès qu'une qualification vient
  // d'être validée — avec le même filet de sécurité décalé de 1,5s.
  useEffect(() => {
    if (!refreshTrigger || !showTraitees) return;
    fetchTraitees();
    const t = setTimeout(fetchTraitees, 1500);
    return () => clearTimeout(t);
  }, [refreshTrigger]); // eslint-disable-line

  function jourLabel(dateStr) {
    const d = new Date(dateStr);
    const auj = new Date(); auj.setHours(0, 0, 0, 0);
    const jd = new Date(d); jd.setHours(0, 0, 0, 0);
    const diffJours = Math.round((jd - auj) / (24 * 3600 * 1000));
    if (diffJours === 0) return "Aujourd'hui";
    if (diffJours === 1) return "Demain";
    return d.toLocaleDateString("fr-FR", { weekday: "long", day: "numeric" });
  }

  return (
    <div className="flex flex-col gap-4">
      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "hidden" }}>
        <button onClick={() => setShowRappels((v) => !v)} className="flex items-center justify-between" style={{ width: "100%", padding: "13px 16px", background: "none", border: "none", cursor: "pointer" }}>
          <span className="flex items-center gap-2" style={{ fontSize: 13, fontWeight: 700, color: C.ink }}>
            <BellRing size={13} color={C.amber} /> Rappels de la semaine{rappels && rappels.length > 0 ? ` (${rappels.length})` : ""}
          </span>
          {showRappels ? <ChevronUp size={14} color={C.mutedSoft} /> : <ChevronDown size={14} color={C.mutedSoft} />}
        </button>
        {showRappels && (
          <div style={{ borderTop: `1px solid ${C.borderSoft}`, padding: 16, maxHeight: 340, overflowY: "auto" }}>
            {error ? (
              <p style={{ fontSize: 11.5, color: C.red }}>{error}</p>
            ) : rappels === null ? (
              <CenterLoader />
            ) : rappels.length === 0 ? (
              <p style={{ fontSize: 12, color: C.mutedSoft }}>Aucun rappel programmé cette semaine.</p>
            ) : (
              <div className="flex flex-col gap-2.5">
                {rappels.map((r) => (
                  <div key={r.id} style={{ borderLeft: `2px solid ${C.amber}`, paddingLeft: 9 }}>
                    <div style={{ fontSize: 10, color: C.amber, fontWeight: 600, textTransform: "capitalize" }}>
                      {jourLabel(r.visible_apres)} · {new Date(r.visible_apres).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}
                    </div>
                    <div style={{ fontSize: 12.5, fontWeight: 500 }}>{r.nom}</div>
                    <div className="mono" style={{ fontSize: 10.5, color: C.mutedSoft }}>#{r.numero_fiche}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "hidden" }}>
        <button onClick={loadTraitees} className="flex items-center justify-between" style={{ width: "100%", padding: "13px 16px", background: "none", border: "none", cursor: "pointer" }}>
          <span className="flex items-center gap-2" style={{ fontSize: 13, fontWeight: 700, color: C.ink }}>
            <History size={13} color={C.muted} /> Fiches traitées aujourd'hui
          </span>
          {showTraitees ? <ChevronUp size={14} color={C.mutedSoft} /> : <ChevronDown size={14} color={C.mutedSoft} />}
        </button>
        {showTraitees && (
          <div style={{ borderTop: `1px solid ${C.borderSoft}`, maxHeight: 340, overflowY: "auto" }}>
            {traitees === null ? (
              <div style={{ padding: 16 }}><CenterLoader /></div>
            ) : traitees.length === 0 ? (
              <p style={{ fontSize: 12, color: C.mutedSoft, padding: 16 }}>Aucune fiche traitée pour l'instant aujourd'hui.</p>
            ) : (
              traitees.map((t, i) => (
                <div key={i} style={{ padding: "10px 16px", borderTop: i > 0 ? `1px solid ${C.borderSoft}` : "none" }}>
                  <div className="flex items-center justify-between">
                    <span style={{ fontSize: 12.5, fontWeight: 500 }}>{t.clients?.nom || "Client"}</span>
                    <span className="mono" style={{ fontSize: 10, color: C.mutedSoft }}>{new Date(t.created_at).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}</span>
                  </div>
                  <div style={{ fontSize: 10.5, color: C.muted, marginTop: 1 }}>
                    {t.types_qualification?.categorie} — {t.types_qualification?.motif}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function AgentSearch({ accessToken, agentId, onAfficher }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState(null);
  const [horsZone, setHorsZone] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [openingId, setOpeningId] = useState(null);

  async function runSearch(e) {
    e.preventDefault();
    const q = query.trim();
    if (!q) { setResults(null); setHorsZone(false); return; }
    setLoading(true); setError(null); setHorsZone(false);
    try {
      // Périmètre de campagnes de l'agent, via ses lots (directs ou de groupe)
      const membres = await supaRest(`groupes_agents_membres?select=groupe_id&agent_id=eq.${agentId}`, { accessToken });
      const groupeIds = membres.map((m) => m.groupe_id);
      const orPartsCibles = [`and(cible_type.eq.agent,agent_id.eq.${agentId})`];
      if (groupeIds.length > 0) orPartsCibles.push(`and(cible_type.eq.groupe,groupe_id.in.(${groupeIds.join(",")}))`);
      const cibles = await supaRest(`lots_cibles?select=lot_id&or=(${orPartsCibles.join(",")})`, { accessToken });
      const monLotIds = [...new Set(cibles.map((c) => c.lot_id))];
      const mesLots = monLotIds.length > 0 ? await supaRest(`lots?select=id,campagne_id&id=in.(${monLotIds.join(",")})`, { accessToken }) : [];
      const mesCampagneIds = new Set(mesLots.map((l) => l.campagne_id));

      const escaped = q.replace(/[%,]/g, "");
      const isNumeric = /^\d+$/.test(q);
      const orParts = [`nom.ilike.*${escaped}*`, `telephone.ilike.*${escaped}*`, `numero_box.ilike.*${escaped}*`];
      if (isNumeric) orParts.push(`numero_fiche.eq.${q}`);
      const rows = await supaRest(`clients?select=*,lots(campagne_id)&or=(${orParts.join(",")})&order=created_at.desc&limit=30`, { accessToken });

      const dansCampagne = rows.filter((r) => !r.lot_id || mesCampagneIds.has(r.lots?.campagne_id));
      setResults(dansCampagne);
      setHorsZone(dansCampagne.length === 0 && rows.length > 0);
    } catch (e) { setError(e.message); } finally { setLoading(false); }
  }

  async function handleAfficher(client) {
    setOpeningId(client.id); setError(null);
    try {
      const [updated] = await supaRest(`clients?id=eq.${client.id}`, {
        method: "PATCH", accessToken, body: { statut: "en_cours", agent_id: agentId },
      });
      onAfficher(updated || client);
    } catch (e) { setError(e.message); } finally { setOpeningId(null); }
  }

  return (
    <div>
      <form onSubmit={runSearch} className="flex items-center gap-2 mb-6" style={{ maxWidth: 480 }}>
        <div className="flex items-center gap-2" style={{ flex: 1, background: C.surface, border: `1px solid ${C.border}`, borderRadius: 9, padding: "9px 12px" }}>
          <Search size={15} color={C.mutedSoft} />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="N° de box, nom du client, téléphone…"
            style={{ border: "none", outline: "none", fontSize: 13, flex: 1 }} />
        </div>
        <button type="submit" style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 9, padding: "10px 16px", fontSize: 13, fontWeight: 600, display: "flex", alignItems: "center", gap: 6 }}>
          {loading ? <Loader2 size={14} className="animate-spin" /> : <Search size={14} />} Rechercher
        </button>
      </form>

      {error && <ErrorBlock message={error} />}
      {horsZone && (
        <div className="flex items-center gap-2" style={{ background: C.redSoft, color: C.red, borderRadius: 9, padding: "12px 16px", fontSize: 13, maxWidth: 520 }}>
          <AlertTriangle size={15} /> Vous n'avez pas le droit d'excéder votre zone de campagne.
        </div>
      )}

      {!horsZone && results && (
        results.length === 0 ? (
          <p style={{ fontSize: 13, color: C.muted }}>Aucune fiche ne correspond à cette recherche.</p>
        ) : (
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "hidden" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
              <thead>
                <tr style={{ background: C.canvas, textAlign: "left" }}>
                  {["N° de box", "N° de fiche", "Client", "Téléphone", "Statut", ""].map((h) => (
                    <th key={h} style={{ padding: "10px 16px", color: C.muted, fontWeight: 600, fontSize: 11, textTransform: "uppercase", letterSpacing: "0.03em" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {results.map((c) => {
                  const meta = STATUS_META[c.statut];
                  return (
                    <tr key={c.id} style={{ borderTop: `1px solid ${C.borderSoft}` }}>
                      <td className="mono" style={{ padding: "10px 16px", color: C.mutedSoft }}>{c.numero_box || "—"}</td>
                      <td className="mono" style={{ padding: "10px 16px", color: C.mutedSoft }}>{c.numero_fiche}</td>
                      <td style={{ padding: "10px 16px", fontWeight: 500 }}>{c.nom}</td>
                      <td className="mono" style={{ padding: "10px 16px" }}>{c.telephone || "—"}</td>
                      <td style={{ padding: "10px 16px" }}>
                        <span style={{ background: meta.soft, color: meta.color, padding: "2px 9px", borderRadius: 999, fontSize: 11, fontWeight: 600 }}>{meta.label}</span>
                      </td>
                      <td style={{ padding: "10px 16px" }}>
                        <button onClick={() => handleAfficher(c)} disabled={openingId === c.id}
                          style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 7, padding: "6px 12px", fontSize: 11.5, fontWeight: 600, display: "flex", alignItems: "center", gap: 5, whiteSpace: "nowrap" }}>
                          {openingId === c.id && <Loader2 size={11} className="animate-spin" />} Afficher
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )
      )}
    </div>
  );
}

function FicheField({ label, value, icon: Icon, mono }) {
  return (
    <div>
      <div className="flex items-center gap-1.5" style={{ fontSize: 10.5, color: C.mutedSoft, textTransform: "uppercase", letterSpacing: "0.03em", marginBottom: 3 }}>
        <Icon size={11} /> {label}
      </div>
      <div className={mono ? "mono" : undefined} style={{ fontSize: 13, fontWeight: 500, color: value ? C.text : C.mutedSoft }}>
        {value || "—"}
      </div>
    </div>
  );
}

function CreateClientPanel({ accessToken, agentId, onClose, onCreated }) {
  const [form, setForm] = useState({ nom: "", telephone: "", numero_mtn: "", segment: "", commune: "", numero_box: "", email: "", note: "" });
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const [myLots, setMyLots] = useState(null); // null = chargement
  const [selectedLotId, setSelectedLotId] = useState("");

  useEffect(() => {
    (async () => {
      try {
        const membres = await supaRest(`groupes_agents_membres?select=groupe_id&agent_id=eq.${agentId}`, { accessToken });
        const groupeIds = membres.map((m) => m.groupe_id);
        const orParts = [`and(cible_type.eq.agent,agent_id.eq.${agentId})`];
        if (groupeIds.length > 0) orParts.push(`and(cible_type.eq.groupe,groupe_id.in.(${groupeIds.join(",")}))`);
        const cibles = await supaRest(`lots_cibles?select=lot_id&or=(${orParts.join(",")})`, { accessToken });
        const lotIds = [...new Set(cibles.map((c) => c.lot_id))];
        const tous = lotIds.length > 0
          ? await supaRest(`lots?select=id,nom,campagne_id,campagnes(nom)&id=in.(${lotIds.join(",")})`, { accessToken })
          : [];
        setMyLots(tous);
        if (tous.length === 1) setSelectedLotId(tous[0].id);
      } catch {
        setMyLots([]);
      }
    })();
  }, [accessToken, agentId]);

  function set(field, value) { setForm((f) => ({ ...f, [field]: value })); }

  async function handleCreate() {
    setError(null);
    if (!form.nom.trim()) { setError("Le nom du client est obligatoire."); return; }
    if (!form.telephone.trim()) { setError("Le numéro de contact 1 est obligatoire pour vérifier les doublons."); return; }
    if (!selectedLotId) { setError("Aucun lot rattaché à votre compte — la fiche ne pourrait jamais être redistribuée. Contactez un administrateur."); return; }
    setBusy(true);
    try {
      // Vérifie si ce client existe déjà et appartient déjà à une campagne (via un lot)
      const orParts = [`telephone.eq.${form.telephone.trim()}`];
      if (form.numero_box.trim()) orParts.push(`numero_box.eq.${form.numero_box.trim()}`);
      const existing = await supaRest(`clients?select=id,nom,lot_id,lots(nom,campagne_id,campagnes(nom))&or=(${orParts.join(",")})`, { accessToken });
      const dejaEnCampagne = existing.find((c) => c.lot_id);
      if (dejaEnCampagne) {
        const nomCampagne = dejaEnCampagne.lots?.campagnes?.nom;
        setError(`Ce client existe déjà dans une campagne${nomCampagne ? ` (« ${nomCampagne} »)` : ""}. Utilisez la recherche pour retrouver sa fiche plutôt que d'en créer une nouvelle.`);
        setBusy(false);
        return;
      }
      const [created] = await supaRest("clients", {
        method: "POST", accessToken,
        body: {
          nom: form.nom.trim(),
          telephone: form.telephone.trim() || null,
          numero_mtn: form.numero_mtn.trim() || null,
          segment: form.segment.trim() || null,
          commune: form.commune.trim() || null,
          numero_box: form.numero_box.trim() || null,
          email: form.email.trim() || null,
          note: form.note.trim() || null,
          lot_id: selectedLotId,
          statut: "en_cours",
          agent_id: agentId,
        },
      });
      onCreated(created);
    } catch (e) { setError(e.message); } finally { setBusy(false); }
  }

  return (
    <div style={{ background: C.surface, border: `1.5px solid ${C.ink}`, borderRadius: 14, padding: 20, marginBottom: 20 }}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Phone size={15} color={C.teal} />
          <h3 className="disp" style={{ fontSize: 15, fontWeight: 700 }}>Créer un client — appel entrant</h3>
        </div>
        <button onClick={onClose} style={{ background: "none", border: "none", color: C.mutedSoft, padding: 4 }}><X size={16} /></button>
      </div>
      <p style={{ fontSize: 11.5, color: C.mutedSoft, marginBottom: 14 }}>
        Réservé aux clients qui n'existent dans aucune campagne. Si le numéro correspond à une fiche déjà en campagne, la création sera bloquée.
      </p>

      <div style={{ background: C.canvas, borderRadius: 8, padding: 10, marginBottom: 14 }}>
        {myLots === null ? (
          <span style={{ fontSize: 12, color: C.mutedSoft }}>Chargement de vos lots…</span>
        ) : myLots.length === 0 ? (
          <span style={{ fontSize: 12, color: C.red }}>Vous n'êtes rattaché à aucun lot. La création sera bloquée — contactez un administrateur.</span>
        ) : myLots.length === 1 ? (
          <span style={{ fontSize: 12, color: C.text }}>
            Sera ajoutée au lot <strong>{myLots[0].nom}</strong> ({myLots[0].campagnes?.nom || "campagne inconnue"}).
          </span>
        ) : (
          <div className="flex items-center gap-2">
            <span style={{ fontSize: 12, color: C.text, whiteSpace: "nowrap" }}>Ajouter au lot :</span>
            <select value={selectedLotId} onChange={(e) => setSelectedLotId(e.target.value)}
              style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 6, padding: "5px 8px", fontSize: 12, background: C.surface }}>
              <option value="">Choisir…</option>
              {myLots.map((l) => (
                <option key={l.id} value={l.id}>{l.nom} — {l.campagnes?.nom || "?"}</option>
              ))}
            </select>
          </div>
        )}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        <input value={form.nom} onChange={(e) => set("nom", e.target.value)} placeholder="Nom du client *"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.telephone} onChange={(e) => set("telephone", e.target.value)} placeholder="Numéro de contact 1 *"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.numero_mtn} onChange={(e) => set("numero_mtn", e.target.value)} placeholder="Numéro MTN"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.segment} onChange={(e) => set("segment", e.target.value)} placeholder="Type de segment"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.commune} onChange={(e) => set("commune", e.target.value)} placeholder="Commune"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.numero_box} onChange={(e) => set("numero_box", e.target.value)} placeholder="Numéro de box (si connu)"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.email} onChange={(e) => set("email", e.target.value)} placeholder="Email"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
        <input value={form.note} onChange={(e) => set("note", e.target.value)} placeholder="Note"
          style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
      </div>

      {error && <div className="mt-3"><ErrorBlock message={error} /></div>}

      <div className="flex items-center gap-2 mt-4">
        <button onClick={handleCreate} disabled={busy}
          style={{ background: C.amber, color: C.ink, border: "none", borderRadius: 8, padding: "10px 18px", fontSize: 13, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
          {busy && <Loader2 size={13} className="animate-spin" />} Créer et ouvrir la fiche
        </button>
        <button onClick={onClose} style={{ background: "none", border: "none", color: C.muted, fontSize: 13 }}>Annuler</button>
      </div>
    </div>
  );
}
