function SearchPanel({ accessToken, tree, isAdmin }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [expandedId, setExpandedId] = useState(null);
  const [derniereQualif, setDerniereQualif] = useState(null);
  const [annulationEnCours, setAnnulationEnCours] = useState(false);
  const [confirmAnnulation, setConfirmAnnulation] = useState(false);

  async function toggleExpand(client) {
    if (expandedId === client.id) { setExpandedId(null); return; }
    setExpandedId(client.id); setDerniereQualif(undefined); setConfirmAnnulation(false);
    try {
      const rows = await supaRest(
        `qualifications?select=id,created_at,commentaire,agent_id,types_qualification(categorie,motif),profils(nom)&client_id=eq.${client.id}&order=created_at.desc&limit=1`,
        { accessToken }
      );
      setDerniereQualif(rows[0] || null);
    } catch { setDerniereQualif(null); }
  }

  async function annuler(clientId) {
    setAnnulationEnCours(true); setError(null);
    try {
      await rpc("annuler_derniere_qualification", accessToken, { p_client_id: clientId });
      setExpandedId(null); setConfirmAnnulation(false);
      runSearchAgain();
    } catch (e) { setError(e.message); } finally { setAnnulationEnCours(false); }
  }

  function runSearchAgain() {
    if (query.trim()) runSearch({ preventDefault: () => {} });
  }

  async function runSearch(e) {
    e.preventDefault();
    const q = query.trim();
    if (!q) { setResults(null); return; }
    setLoading(true); setError(null);
    try {
      const escaped = q.replace(/[%,]/g, "");
      const isNumeric = /^\d+$/.test(q);
      const orParts = [`nom.ilike.*${escaped}*`, `telephone.ilike.*${escaped}*`, `email.ilike.*${escaped}*`, `numero_box.ilike.*${escaped}*`];
      if (isNumeric) orParts.push(`numero_fiche.eq.${q}`);
      const rows = await supaRest(`clients?select=*&or=(${orParts.join(",")})&order=created_at.desc&limit=30`, { accessToken });
      setResults(rows);
    } catch (e) { setError(e.message); } finally { setLoading(false); }
  }

  return (
    <div>
      <header className="mb-6">
        <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Recherche</h1>
        <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Par numéro de fiche, numéro de box, nom du client ou numéro de contact.</p>
      </header>

      <form onSubmit={runSearch} className="flex items-center gap-2 mb-6" style={{ maxWidth: 480 }}>
        <div className="flex items-center gap-2" style={{ flex: 1, background: C.surface, border: `1px solid ${C.border}`, borderRadius: 9, padding: "9px 12px" }}>
          <Search size={15} color={C.mutedSoft} />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="N° de fiche, N° de box, nom, téléphone…"
            style={{ border: "none", outline: "none", fontSize: 13, flex: 1 }} />
        </div>
        <button type="submit" style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 9, padding: "10px 16px", fontSize: 13, fontWeight: 600, display: "flex", alignItems: "center", gap: 6 }}>
          {loading ? <Loader2 size={14} className="animate-spin" /> : <Search size={14} />} Rechercher
        </button>
      </form>

      {error && <ErrorBlock message={error} />}

      {results && (
        results.length === 0 ? (
          <p style={{ fontSize: 13, color: C.muted }}>Aucune fiche ne correspond à cette recherche.</p>
        ) : (
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "hidden" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
              <thead>
                <tr style={{ background: C.canvas, textAlign: "left" }}>
                  {["N° de fiche", "N° de box", "Client", "Téléphone", "Statut"].map((h) => (
                    <th key={h} style={{ padding: "10px 16px", color: C.muted, fontWeight: 600, fontSize: 11, textTransform: "uppercase", letterSpacing: "0.03em" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {results.map((c) => {
                  const meta = STATUS_META[c.statut];
                  const isExpanded = expandedId === c.id;
                  return (
                    <Fragment key={c.id}>
                    <tr onClick={() => toggleExpand(c)} style={{ borderTop: `1px solid ${C.borderSoft}`, cursor: "pointer", background: isExpanded ? C.canvas : "transparent" }}>
                      <td className="mono" style={{ padding: "10px 16px", color: C.mutedSoft }}>{c.numero_fiche}</td>
                      <td className="mono" style={{ padding: "10px 16px", color: C.mutedSoft }}>{c.numero_box || "—"}</td>
                      <td style={{ padding: "10px 16px", fontWeight: 500 }}>{c.nom}</td>
                      <td className="mono" style={{ padding: "10px 16px" }}>{c.telephone || "—"}</td>
                      <td style={{ padding: "10px 16px" }}>
                        <span style={{ background: meta.soft, color: meta.color, padding: "2px 9px", borderRadius: 999, fontSize: 11, fontWeight: 600 }}>{meta.label}</span>
                      </td>
                    </tr>
                    {isExpanded && (
                      <tr>
                        <td colSpan={5} style={{ padding: "14px 16px", background: C.canvas, borderTop: `1px solid ${C.borderSoft}` }}>
                          {derniereQualif === undefined ? (
                            <CenterLoader />
                          ) : derniereQualif === null ? (
                            <p style={{ fontSize: 12.5, color: C.mutedSoft }}>Aucune qualification enregistrée pour cette fiche.</p>
                          ) : (
                            <div className="flex items-center justify-between">
                              <div>
                                <div style={{ fontSize: 12.5, fontWeight: 600 }}>
                                  {derniereQualif.types_qualification?.categorie} · {derniereQualif.types_qualification?.motif}
                                </div>
                                <div style={{ fontSize: 11.5, color: C.muted, marginTop: 2 }}>
                                  Par {derniereQualif.profils?.nom || "agent"} · {new Date(derniereQualif.created_at).toLocaleString("fr-FR")}
                                </div>
                                {derniereQualif.commentaire && (
                                  <p style={{ fontSize: 11.5, color: C.muted, marginTop: 4, fontStyle: "italic" }}>« {derniereQualif.commentaire} »</p>
                                )}
                              </div>
                              {isAdmin && (
                                confirmAnnulation ? (
                                  <div className="flex items-center gap-2">
                                    <span style={{ fontSize: 11.5, color: C.red }}>Confirmer l'annulation ?</span>
                                    <button onClick={() => annuler(c.id)} disabled={annulationEnCours}
                                      style={{ background: C.red, color: "#fff", border: "none", borderRadius: 7, padding: "7px 12px", fontSize: 12, fontWeight: 600 }}>
                                      {annulationEnCours ? <Loader2 size={12} className="animate-spin" /> : "Oui, annuler"}
                                    </button>
                                    <button onClick={() => setConfirmAnnulation(false)}
                                      style={{ background: "none", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 12px", fontSize: 12 }}>
                                      Non
                                    </button>
                                  </div>
                                ) : (
                                  <button onClick={() => setConfirmAnnulation(true)}
                                    className="flex items-center gap-1.5" style={{ background: "none", border: `1px solid ${C.red}`, color: C.red, borderRadius: 7, padding: "7px 12px", fontSize: 12, fontWeight: 600 }}>
                                    <RotateCcw size={12} /> Annuler cette qualification
                                  </button>
                                )
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                    )}
                    </Fragment>
                  );
                })}
              </tbody>
            </table>
          </div>
        )
      )}
    </div>
  );
}

/* ---------------------------------- admin : dashboard ---------------------------------- */

function debutPeriode(periode) {
  const now = new Date();
  if (periode === "jour") {
    return new Date(now.getFullYear(), now.getMonth(), now.getDate());
  }
  if (periode === "semaine") {
    const jour = (now.getDay() + 6) % 7; // lundi = 0
    return new Date(now.getFullYear(), now.getMonth(), now.getDate() - jour);
  }
  return new Date(now.getFullYear(), now.getMonth(), 1); // mois
}
function finPeriode(periode, debut) {
  if (periode === "jour") return new Date(debut.getTime() + 24 * 3600 * 1000);
  if (periode === "semaine") return new Date(debut.getTime() + 7 * 24 * 3600 * 1000);
  return new Date(debut.getFullYear(), debut.getMonth() + 1, 1); // mois
}
function formatRelatif(dateStr) {
  if (!dateStr) return "";
  const s = Math.floor((Date.now() - new Date(dateStr).getTime()) / 1000);
  if (s < 60) return "à l'instant";
  if (s < 3600) return `il y a ${Math.floor(s / 60)} min`;
  if (s < 86400) return `il y a ${Math.floor(s / 3600)} h`;
  return `il y a ${Math.floor(s / 86400)} j`;
}

function formatDuree(secondes) {
  if (secondes === null || secondes === undefined) return "—";
  const m = Math.floor(secondes / 60), s = Math.round(secondes % 60);
  return `${m}min ${String(s).padStart(2, "0")}s`;
}

/* ---------------------------------- statut en direct de l'équipe ---------------------------------- */

function LiveStatusPanel({ accessToken, callerRole }) {
  const [rows, setRows] = useState(null);
  const [pauseTypesList, setPauseTypesList] = useState([]);
  const [error, setError] = useState(null);
  const [openMenuId, setOpenMenuId] = useState(null);
  const [busyId, setBusyId] = useState(null);

  const peutControler = ["admin", "super_admin", "superviseur"].includes(callerRole);

  const load = useCallback(async () => {
    try {
      const perimetre = await rpc("mon_perimetre_personnes", accessToken, {});
      const ids = (perimetre || []).map((r) => r.profil_id);
      if (ids.length === 0) { setRows([]); return; }
      const [profils, pauseTypes, pausesOuvertes] = await Promise.all([
        fetchInChunks(`profils?select=id,nom,role,matricule,statut&role=in.(agent,superviseur,coach)&id=in.(`, ids, accessToken),
        supaRest("pause_types?select=*&actif=eq.true&order=ordre.asc", { accessToken }),
        fetchInChunks(`pause_details?select=agent_id,pause_type_id&fin=is.null&agent_id=in.(`, ids, accessToken),
      ]);
      setPauseTypesList(pauseTypes);
      const list = profils.map((p) => {
        const pauseOuverte = pausesOuvertes.find((d) => d.agent_id === p.id);
        const pauseType = pauseOuverte ? pauseTypes.find((t) => t.id === pauseOuverte.pause_type_id) : null;
        return { ...p, pauseLabel: pauseType?.nom || null, pauseCouleur: pauseType?.couleur || null };
      });
      list.sort((a, b) => {
        const ordre = { en_prod: 0, en_pause: 1, deconnecte: 2 };
        return (ordre[a.statut] ?? 3) - (ordre[b.statut] ?? 3) || a.nom.localeCompare(b.nom);
      });
      setRows(list);
    } catch (e) { setError(e.message); }
  }, [accessToken]);

  useEffect(() => { load(); const t = setInterval(load, 30000); return () => clearInterval(t); }, [load]);

  async function forcerStatut(agentId, statut, pauseTypeId = null) {
    setBusyId(agentId); setOpenMenuId(null);
    try {
      await rpc("forcer_statut_agent", accessToken, { p_agent_id: agentId, p_statut: statut, p_pause_type_id: pauseTypeId });
      load();
    } catch (e) { setError(e.message); } finally { setBusyId(null); }
  }

  if (error) return null; // discret : ne casse pas le reste du tableau de bord
  if (!rows) return <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18, marginBottom: 16 }}><CenterLoader /></div>;

  return (
    <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18, marginBottom: 16 }}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <CircleDot size={14} color={C.green} />
          <h2 className="disp" style={{ fontSize: 15, fontWeight: 600 }}>Statut en direct</h2>
        </div>
        <span style={{ fontSize: 10.5, color: C.mutedSoft }}>Actualisé toutes les 30 secondes</span>
      </div>
      {rows.length === 0 ? (
        <p style={{ fontSize: 12.5, color: C.muted }}>Aucune personne dans votre périmètre.</p>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(210px, 1fr))", gap: 8 }}>
          {rows.map((p) => {
            const st = AGENT_STATUTS.find((s) => s.id === p.statut);
            const dotColor = p.statut === "en_prod" ? C.green : p.statut === "en_pause" ? (p.pauseCouleur || C.amber) : C.mutedSoft;
            const label = p.statut === "en_pause" && p.pauseLabel ? p.pauseLabel : (st?.label || p.statut);
            const menuOuvert = openMenuId === p.id;
            return (
              <div key={p.id} style={{ position: "relative" }}>
                <div className="flex items-center gap-2.5" onClick={() => peutControler && setOpenMenuId(menuOuvert ? null : p.id)}
                  style={{ background: C.canvas, borderRadius: 9, padding: "9px 12px", cursor: peutControler ? "pointer" : "default" }}>
                  {busyId === p.id ? (
                    <Loader2 size={11} className="animate-spin" style={{ flexShrink: 0 }} />
                  ) : (
                    <span style={{ width: 8, height: 8, borderRadius: 999, background: dotColor, flexShrink: 0, boxShadow: p.statut === "en_prod" ? `0 0 0 3px ${C.greenSoft}` : "none" }} />
                  )}
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <div style={{ fontSize: 12.5, fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.nom}</div>
                    <div style={{ fontSize: 10.5, color: C.muted }}>{label}</div>
                  </div>
                  {peutControler && <ChevronDown size={12} color={C.mutedSoft} style={{ flexShrink: 0 }} />}
                </div>
                {menuOuvert && (
                  <div style={{ position: "absolute", top: "100%", left: 0, right: 0, marginTop: 4, background: C.surface, border: `1px solid ${C.border}`, borderRadius: 9, boxShadow: "0 8px 20px rgba(0,0,0,0.12)", zIndex: 20, overflow: "hidden" }}>
                    <button onClick={() => forcerStatut(p.id, "en_prod")}
                      className="flex items-center gap-2" style={{ width: "100%", padding: "8px 12px", background: "none", border: "none", fontSize: 12, textAlign: "left" }}>
                      <PlayCircle size={12} color={C.green} /> Production
                    </button>
                    <div style={{ borderTop: `1px solid ${C.borderSoft}`, padding: "6px 12px 2px", fontSize: 9.5, color: C.mutedSoft, textTransform: "uppercase" }}>Pause</div>
                    {pauseTypesList.map((pt) => (
                      <button key={pt.id} onClick={() => forcerStatut(p.id, "en_pause", pt.id)}
                        className="flex items-center gap-2" style={{ width: "100%", padding: "7px 12px", background: "none", border: "none", fontSize: 12, textAlign: "left" }}>
                        <span style={{ width: 7, height: 7, borderRadius: 999, background: pt.couleur || C.amber }} /> {pt.nom}
                      </button>
                    ))}
                    <button onClick={() => forcerStatut(p.id, "deconnecte")}
                      className="flex items-center gap-2" style={{ width: "100%", padding: "8px 12px", background: "none", border: "none", borderTop: `1px solid ${C.borderSoft}`, fontSize: 12, textAlign: "left", color: C.red }}>
                      <PowerOff size={12} /> Déconnecter
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------- fiches bloquées de l'équipe (vue d'ensemble) ---------------------------------- */

function FichesBloqueesEquipe({ accessToken }) {
  const [rows, setRows] = useState(null);
  const [error, setError] = useState(null);
  const [liberationEnCours, setLiberationEnCours] = useState(null);

  const load = useCallback(async () => {
    try {
      const perimetre = await rpc("mon_perimetre_agents", accessToken, {});
      const agentIds = (perimetre || []).map((r) => r.agent_id);
      if (agentIds.length === 0) { setRows([]); return; }
      const [clients, profils] = await Promise.all([
        fetchInChunks(`clients?select=id,nom,numero_fiche,agent_id,updated_at&statut=eq.en_cours&agent_id=in.(`, agentIds, accessToken),
        fetchInChunks(`profils?select=id,nom&id=in.(`, agentIds, accessToken),
      ]);
      const merged = clients.map((c) => ({ ...c, agentNom: profils.find((p) => p.id === c.agent_id)?.nom || "Agent" }));
      merged.sort((a, b) => new Date(a.updated_at) - new Date(b.updated_at));
      setRows(merged);
    } catch (e) { setError(e.message); }
  }, [accessToken]);

  useEffect(() => { load(); const t = setInterval(load, 30000); return () => clearInterval(t); }, [load]);

  async function liberer(clientId) {
    setLiberationEnCours(clientId); setError(null);
    try {
      await rpc("liberer_fiche_bloquee", accessToken, { p_client_id: clientId });
      load();
    } catch (e) { setError(e.message); } finally { setLiberationEnCours(null); }
  }

  if (error) return <div className="mb-4"><ErrorBlock message={error} /></div>;
  if (!rows || rows.length === 0) return null; // rien à signaler : on ne surcharge pas l'écran

  return (
    <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 12, padding: 18, marginBottom: 16 }}>
      <div className="flex items-center gap-2 mb-4">
        <AlertTriangle size={14} color={C.amber} />
        <h2 className="disp" style={{ fontSize: 15, fontWeight: 600 }}>Fiches bloquées de l'équipe</h2>
        <span style={{ fontSize: 11, color: C.muted }}>— jamais qualifiées, sans doute oubliées</span>
      </div>
      <div className="flex flex-col gap-2">
        {rows.map((r) => (
          <div key={r.id} className="flex items-center justify-between" style={{ background: C.surface, borderRadius: 9, padding: "9px 14px" }}>
            <div>
              <span style={{ fontSize: 12.5, fontWeight: 500 }}>{r.nom}</span>
              <span className="mono" style={{ fontSize: 11, color: C.mutedSoft, marginLeft: 8 }}>#{r.numero_fiche}</span>
              <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{r.agentNom} · récupérée {formatRelatif(r.updated_at)}</div>
            </div>
            <button onClick={() => liberer(r.id)} disabled={liberationEnCours === r.id}
              className="flex items-center gap-1.5" style={{ background: "none", border: `1px solid ${C.border}`, borderRadius: 7, padding: "6px 12px", fontSize: 12, fontWeight: 600, color: C.ink }}>
              {liberationEnCours === r.id ? <Loader2 size={11} className="animate-spin" /> : <RotateCcw size={11} />} Libérer
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ---------------------------------- mes résultats (calendrier multi-sélection) ---------------------------------- */

const JOURS_SEMAINE = ["L", "M", "M", "J", "V", "S", "D"];
const MOIS_NOMS = ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"];

function toISODate(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function MultiCalendar({ selected, onToggle }) {
  const [viewDate, setViewDate] = useState(new Date());
  const annee = viewDate.getFullYear(), mois = viewDate.getMonth();
  const premierJour = new Date(annee, mois, 1);
  const decalage = (premierJour.getDay() + 6) % 7; // lundi = 0
  const nbJours = new Date(annee, mois + 1, 0).getDate();
  const todayISO = toISODate(new Date());

  const cases = [];
  for (let i = 0; i < decalage; i++) cases.push(null);
  for (let j = 1; j <= nbJours; j++) cases.push(j);

  return (
    <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 16, width: 300 }}>
      <div className="flex items-center justify-between mb-3">
        <button onClick={() => setViewDate(new Date(annee, mois - 1, 1))} style={{ background: "none", border: "none", padding: 4, color: C.muted }}>
          <ArrowRight size={14} style={{ transform: "rotate(180deg)" }} />
        </button>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{MOIS_NOMS[mois]} {annee}</span>
        <button onClick={() => setViewDate(new Date(annee, mois + 1, 1))} style={{ background: "none", border: "none", padding: 4, color: C.muted }}>
          <ArrowRight size={14} />
        </button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 3, marginBottom: 4 }}>
        {JOURS_SEMAINE.map((j, i) => (
          <div key={i} style={{ textAlign: "center", fontSize: 10, color: C.mutedSoft, fontWeight: 600 }}>{j}</div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 3 }}>
        {cases.map((jour, i) => {
          if (jour === null) return <div key={i} />;
          const iso = toISODate(new Date(annee, mois, jour));
          const isSelected = selected.includes(iso);
          const isToday = iso === todayISO;
          return (
            <button key={i} onClick={() => onToggle(iso)}
              style={{
                aspectRatio: "1", borderRadius: 7, fontSize: 12, fontWeight: isSelected ? 700 : 500,
                background: isSelected ? C.ink : "transparent", color: isSelected ? "#fff" : C.text,
                border: isToday && !isSelected ? `1.5px solid ${C.amber}` : "1.5px solid transparent",
              }}>
              {jour}
            </button>
          );
        })}
      </div>
    </div>
  );
}

