function Dashboard({ accessToken, refreshFlag, callerRole }) {
  const [counts, setCounts] = useState(null);
  const [parAgent, setParAgent] = useState(null);
  const [perf, setPerf] = useState(null); // { traitees, contacts, ventes, dureeMoyenne }
  const [error, setError] = useState(null);
  const [periode, setPeriode] = useState("jour"); // jour | semaine | mois

  const loadDashboard = useCallback(async () => {
    try {
      const statutRows = await supaRest("vue_compte_statuts_clients?select=*", { accessToken });
      const c = { disponible: 0, en_cours: 0, planifie: 0, archive: 0, total: 0 };
      statutRows.forEach((r) => { c[r.statut] = r.total; c.total += r.total; });
      setCounts(c);

      const rappels = await supaRest("vue_rappels_par_agent?select=*", { accessToken });
      const profils = await supaRest("profils?select=id,nom,statut", { accessToken });
      const list = rappels.map((r) => ({
        agentId: r.agent_id, nom: profils.find((p) => p.id === r.agent_id)?.nom || "Agent",
        statut: profils.find((p) => p.id === r.agent_id)?.statut, total: r.total, enRetard: r.en_retard,
      })).sort((a, b) => b.enRetard - a.enRetard || b.total - a.total);
      setParAgent(list);

      // Performance sur la période choisie (jour/semaine/mois), agrégation SQL scopée
      const debut = debutPeriode(periode);
      const fin = finPeriode(periode, debut);
      const [perfRow] = await rpc("perf_periode", accessToken, { p_debut: debut.toISOString(), p_fin: fin.toISOString() });
      setPerf({
        traitees: perfRow?.traitees || 0, contacts: perfRow?.contacts || 0, ventes: perfRow?.ventes || 0,
        dureeMoyenne: perfRow?.duree_moyenne_secondes ?? null,
      });
    } catch (e) { setError(e.message); }
  }, [accessToken, periode]);

  useEffect(() => { loadDashboard(); }, [loadDashboard, refreshFlag]);
  useEffect(() => { const t = setInterval(loadDashboard, 30000); return () => clearInterval(t); }, [loadDashboard]);

  if (error) return <ErrorBlock message={error} />;
  if (!counts) return <CenterLoader />;

  const stats = [
    { label: "Total fiches", value: counts.total, icon: Users, color: C.ink },
    { label: "Disponibles", value: counts.disponible, icon: CircleDot, color: C.teal },
    { label: "En cours", value: counts.en_cours, icon: Timer, color: C.amber },
    { label: "En attente de rappel", value: counts.planifie, icon: Clock, color: C.mutedSoft },
    { label: "Archivées", value: counts.archive, icon: Archive, color: C.muted },
  ];

  const joignabilite = perf && perf.traitees > 0 ? Math.round((perf.contacts / perf.traitees) * 100) : null;
  const conversion = perf && perf.contacts > 0 ? Math.round((perf.ventes / perf.contacts) * 100) : null;

  return (
    <div>
      <header className="mb-5 flex items-end justify-between">
        <div>
          <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Tableau de bord</h1>
          <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Données en direct depuis Supabase — actualisées toutes les 30 secondes.</p>
        </div>
        <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10, padding: 4 }} className="flex gap-1">
          {[{ id: "jour", label: "Jour" }, { id: "semaine", label: "Semaine" }, { id: "mois", label: "Mois" }].map((p) => (
            <button key={p.id} onClick={() => setPeriode(p.id)}
              style={{ padding: "7px 14px", borderRadius: 7, border: "none", background: periode === p.id ? C.ink : "transparent", color: periode === p.id ? "#fff" : C.muted, fontSize: 12.5, fontWeight: 600 }}>
              {p.label}
            </button>
          ))}
        </div>
      </header>
      <p style={{ fontSize: 11, color: C.mutedSoft, marginTop: -12, marginBottom: 16 }}>
        Le calendrier ne s'applique qu'à la performance ci-dessous (joignabilité, conversion, temps de traitement) — les compteurs de fiches reflètent toujours l'état actuel.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 14, marginBottom: 16 }}>
        {stats.map((s) => (
          <div key={s.label} style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18 }}>
            <s.icon size={16} color={s.color} />
            <div className="disp mono" style={{ fontSize: 26, fontWeight: 700, marginTop: 10 }}>{s.value}</div>
            <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 14, marginBottom: 24 }}>
        <div style={{ background: C.ink, borderRadius: 12, padding: 20 }}>
          <div className="flex items-center gap-2" style={{ marginBottom: 10 }}>
            <PhoneOff size={14} color="#A6ADBA" style={{ transform: "rotate(135deg)" }} />
            <span style={{ fontSize: 12, color: "#A6ADBA", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.03em" }}>Taux de joignabilité</span>
          </div>
          <div className="disp mono" style={{ fontSize: 34, fontWeight: 700, color: "#fff" }}>
            {joignabilite === null ? "—" : `${joignabilite}%`}
          </div>
          <div style={{ fontSize: 11.5, color: "#8B93A3", marginTop: 4 }}>
            {perf ? `${perf.contacts} contact${perf.contacts !== 1 ? "s" : ""} sur ${perf.traitees} fiche${perf.traitees !== 1 ? "s" : ""} traitée${perf.traitees !== 1 ? "s" : ""}` : "…"}
          </div>
        </div>
        <div style={{ background: C.ink, borderRadius: 12, padding: 20 }}>
          <div className="flex items-center gap-2" style={{ marginBottom: 10 }}>
            <CheckCircle2 size={14} color={C.amber} />
            <span style={{ fontSize: 12, color: "#A6ADBA", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.03em" }}>Taux de conversion</span>
          </div>
          <div className="disp mono" style={{ fontSize: 34, fontWeight: 700, color: C.amber }}>
            {conversion === null ? "—" : `${conversion}%`}
          </div>
          <div style={{ fontSize: 11.5, color: "#8B93A3", marginTop: 4 }}>
            {perf ? `${perf.ventes} vente${perf.ventes !== 1 ? "s" : ""} sur ${perf.contacts} contact${perf.contacts !== 1 ? "s" : ""}` : "…"}
          </div>
        </div>
        <div style={{ background: C.ink, borderRadius: 12, padding: 20 }}>
          <div className="flex items-center gap-2" style={{ marginBottom: 10 }}>
            <Clock size={14} color={C.teal} />
            <span style={{ fontSize: 12, color: "#A6ADBA", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.03em" }}>Temps moyen / fiche</span>
          </div>
          <div className="disp mono" style={{ fontSize: 34, fontWeight: 700, color: C.teal }}>
            {formatDuree(perf?.dureeMoyenne)}
          </div>
          <div style={{ fontSize: 11.5, color: "#8B93A3", marginTop: 4 }}>
            {perf ? `Sur ${perf.traitees} fiche${perf.traitees !== 1 ? "s" : ""} qualifiée${perf.traitees !== 1 ? "s" : ""}` : "…"}
          </div>
        </div>
      </div>

      <LiveStatusPanel accessToken={accessToken} callerRole={callerRole} />
      <FichesBloqueesEquipe accessToken={accessToken} />

      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18 }}>
        <div className="flex items-center gap-2 mb-4">
          <BellRing size={15} color={C.amber} />
          <h2 className="disp" style={{ fontSize: 15, fontWeight: 600 }}>Rappels non traités par agent</h2>
        </div>
        {!parAgent || parAgent.length === 0 ? (
          <p style={{ fontSize: 12.5, color: C.muted }}>Aucun rappel en attente.</p>
        ) : (
          <div className="flex flex-col gap-2">
            {parAgent.map((a) => (
              <div key={a.agentId} className="flex items-center justify-between" style={{ padding: "9px 12px", background: C.canvas, borderRadius: 8 }}>
                <div className="flex items-center gap-2">
                  <span style={{ fontSize: 12.5, fontWeight: 500 }}>{a.nom}</span>
                  <span style={{ fontSize: 10, color: C.mutedSoft }}>
                    {AGENT_STATUTS.find((s) => s.id === a.statut)?.label || a.statut}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  {a.enRetard > 0 && (
                    <span style={{ background: C.redSoft, color: C.red, fontSize: 11, fontWeight: 700, padding: "2px 9px", borderRadius: 999 }}>
                      {a.enRetard} en retard
                    </span>
                  )}
                  <span style={{ background: C.amberSoft, color: C.amber, fontSize: 11, fontWeight: 700, padding: "2px 9px", borderRadius: 999 }}>
                    {a.total} au total
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* ---------------------------------- admin/superviseur : présence ---------------------------------- */

function PresencePanel({ accessToken }) {
  const [vue, setVue] = useState("jour"); // jour | mois
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [mois, setMois] = useState(() => new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [rows, setRows] = useState(null);
  const [pauseTypesList, setPauseTypesList] = useState([]);
  const [error, setError] = useState(null);
  const [exporting, setExporting] = useState(false);

  const load = useCallback(async () => {
    setRows(null); setError(null);
    try {
      let periodStart, periodEnd, jourGteFilter, jourLtFilter;
      if (vue === "jour") {
        periodStart = new Date(date + "T00:00:00");
        periodEnd = new Date(periodStart.getTime() + 24 * 3600 * 1000);
        jourGteFilter = date; jourLtFilter = date;
      } else {
        periodStart = new Date(mois + "-01T00:00:00");
        periodEnd = new Date(periodStart.getFullYear(), periodStart.getMonth() + 1, 1);
        jourGteFilter = periodStart.toISOString().slice(0, 10);
        jourLtFilter = periodEnd.toISOString().slice(0, 10);
      }
      const perimetre = await rpc("mon_perimetre_personnes", accessToken, {});
      const idsVisibles = (perimetre || []).map((r) => r.profil_id);
      if (idsVisibles.length === 0) { setRows([]); return; }
      const [profils, temps, pauseTypes, pauseDetails, historique] = await Promise.all([
        fetchInChunks(`profils?select=id,nom,role,matricule&role=in.(agent,superviseur,coach)&id=in.(`, idsVisibles, accessToken),
        vue === "jour"
          ? supaRest(`vue_temps_agent_jour?select=agent_id,statut,secondes&jour=eq.${jourGteFilter}`, { accessToken })
          : supaRest(`vue_temps_agent_jour?select=agent_id,statut,secondes&jour=gte.${jourGteFilter}&jour=lt.${jourLtFilter}`, { accessToken }),
        supaRest("pause_types?select=*&order=ordre.asc", { accessToken }),
        supaRest(`pause_details?select=agent_id,pause_type_id,debut,fin&debut=gte.${periodStart.toISOString()}&debut=lt.${periodEnd.toISOString()}`, { accessToken }),
        vue === "jour"
          ? supaRest(`statuts_historique?select=agent_id,statut,debut&debut=gte.${periodStart.toISOString()}&debut=lt.${periodEnd.toISOString()}&order=debut.asc`, { accessToken })
          : Promise.resolve([]), // "heure de connexion" n'a pas de sens agrégée sur un mois
      ]);
      setPauseTypesList(pauseTypes);
      const now = Date.now();
      const connexionParAgent = {};
      for (const h of historique) {
        if (h.statut === "deconnecte") continue; // pas une connexion, on ignore
        if (!connexionParAgent[h.agent_id]) connexionParAgent[h.agent_id] = h.debut;
      }

      const parAgent = profils.map((p) => {
        const enProd = temps.filter((t) => t.agent_id === p.id && t.statut === "en_prod").reduce((s, t) => s + t.secondes, 0);
        const details = pauseDetails.filter((d) => d.agent_id === p.id);
        const byType = {};
        for (const d of details) {
          const pt = pauseTypes.find((t) => t.id === d.pause_type_id);
          if (!pt) continue;
          const finMs = d.fin ? new Date(d.fin).getTime() : now;
          const seconds = Math.max(0, (finMs - new Date(d.debut).getTime()) / 1000);
          if (!byType[pt.code]) byType[pt.code] = { ...pt, seconds: 0 };
          byType[pt.code].seconds += seconds;
        }
        let presenceBrute = enProd, occupationImpact = 0;
        Object.values(byType).forEach((t) => {
          if (t.compte_presence) presenceBrute += t.seconds;
          if (t.compte_occupation) occupationImpact += t.seconds;
        });
        const occupation = (enProd + occupationImpact) > 0 ? enProd / (enProd + occupationImpact) : null;
        return { ...p, enProd, byType, presenceBrute, occupation, heureConnexion: connexionParAgent[p.id] || null };
      });

      parAgent.sort((a, b) => b.presenceBrute - a.presenceBrute);
      setRows(parAgent);
    } catch (e) { setError(e.message); }
  }, [accessToken, date, mois, vue]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => { const t = setInterval(load, 30000); return () => clearInterval(t); }, [load]);

  function exportExcel() {
    setExporting(true);
    try {
      const data = rows.map((a) => {
        const row = {
          Matricule: a.matricule,
          Agent: a.nom,
          Rôle: a.role,
          ...(vue === "jour" ? { "Heure de connexion": a.heureConnexion ? new Date(a.heureConnexion).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" }) : "" } : {}),
          "Temps production": fmtDuration(a.enProd),
          "Temps production (h)": hoursDecimal(a.enProd),
        };
        pauseTypesList.forEach((pt) => {
          const seconds = a.byType[pt.code]?.seconds || 0;
          row[pt.nom] = fmtDuration(seconds);
          row[`${pt.nom} (h)`] = hoursDecimal(seconds);
        });
        row["Présence brute (hors pause déjeuner)"] = fmtDuration(a.presenceBrute);
        row["Présence brute (h)"] = hoursDecimal(a.presenceBrute);
        row["Taux d'occupation (%)"] = a.occupation === null ? "" : Math.round(a.occupation * 100);
        return row;
      });
      const ws = XLSX.utils.json_to_sheet(data);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Présence");
      XLSX.writeFile(wb, `aureo_presence_${vue === "jour" ? date : mois}.xlsx`);
    } finally { setExporting(false); }
  }

  const totaux = rows ? rows.reduce((acc, a) => {
    acc.enProd += a.enProd;
    pauseTypesList.forEach((pt) => { acc.byType[pt.code] = (acc.byType[pt.code] || 0) + (a.byType[pt.code]?.seconds || 0); });
    acc.occupationImpact += Object.values(a.byType).reduce((s, t) => s + (t.compte_occupation ? t.seconds : 0), 0);
    return acc;
  }, { enProd: 0, byType: {}, occupationImpact: 0 }) : null;

  const occupationMoyenne = totaux && (totaux.enProd + totaux.occupationImpact) > 0
    ? totaux.enProd / (totaux.enProd + totaux.occupationImpact) : null;
  const totalPause = totaux ? Object.values(totaux.byType).reduce((s, v) => s + v, 0) : 0;

  function occupationColor(o) {
    if (o === null) return C.mutedSoft;
    if (o >= 0.8) return C.green;
    if (o >= 0.5) return C.amber;
    return C.red;
  }

  return (
    <div>
      <header className="mb-6 flex items-end justify-between">
        <div>
          <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Présence</h1>
          <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Temps de production, pauses par type et taux d'occupation par agent — actualisé toutes les 30 secondes.</p>
        </div>
        <div className="flex items-center gap-2">
          <div style={{ background: C.canvas, borderRadius: 8, padding: 3 }} className="flex gap-1">
            {[{ id: "jour", label: "Jour" }, { id: "mois", label: "Mois" }].map((v) => (
              <button key={v.id} onClick={() => setVue(v.id)}
                style={{ padding: "6px 12px", borderRadius: 6, border: "none", background: vue === v.id ? C.ink : "transparent", color: vue === v.id ? "#fff" : C.muted, fontSize: 12, fontWeight: 600 }}>
                {v.label}
              </button>
            ))}
          </div>
          {vue === "jour" ? (
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)}
              style={{ border: `1px solid ${C.border}`, borderRadius: 8, padding: "8px 10px", fontSize: 13 }} />
          ) : (
            <input type="month" value={mois} onChange={(e) => setMois(e.target.value)}
              style={{ border: `1px solid ${C.border}`, borderRadius: 8, padding: "8px 10px", fontSize: 13 }} />
          )}
          <button onClick={exportExcel} disabled={!rows || rows.length === 0 || exporting}
            style={{ display: "flex", alignItems: "center", gap: 6, background: C.ink, color: "#fff", border: "none", borderRadius: 8, padding: "8px 14px", fontSize: 12.5, fontWeight: 600 }}>
            {exporting ? <Loader2 size={13} className="animate-spin" /> : <FileSpreadsheet size={13} />} Exporter Excel
          </button>
        </div>
      </header>

      {error && <div className="mb-4"><ErrorBlock message={error} /></div>}

      {rows === null ? (
        <CenterLoader />
      ) : (
        <>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14, marginBottom: 24 }}>
            <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18 }}>
              <Users size={16} color={C.ink} />
              <div className="disp mono" style={{ fontSize: 24, fontWeight: 700, marginTop: 10 }}>
                {rows.filter((a) => a.presenceBrute > 0).length} <span style={{ fontSize: 14, color: C.mutedSoft, fontWeight: 500 }}>/ {rows.length}</span>
              </div>
              <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>Actifs ce jour / périmètre total</div>
            </div>
            <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18 }}>
              <PlayCircle size={16} color={C.green} />
              <div className="disp mono" style={{ fontSize: 24, fontWeight: 700, marginTop: 10 }}>{hoursDecimal(totaux.enProd)} h</div>
              <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>Temps de production cumulé</div>
            </div>
            <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18 }}>
              <PauseCircle size={16} color={C.amber} />
              <div className="disp mono" style={{ fontSize: 24, fontWeight: 700, marginTop: 10 }}>{hoursDecimal(totalPause)} h</div>
              <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>Toutes pauses cumulées</div>
            </div>
            <div style={{ background: C.ink, borderRadius: 12, padding: 18 }}>
              <CircleDot size={16} color={occupationColor(occupationMoyenne)} />
              <div className="disp mono" style={{ fontSize: 24, fontWeight: 700, marginTop: 10, color: "#fff" }}>
                {occupationMoyenne === null ? "—" : `${Math.round(occupationMoyenne * 100)}%`}
              </div>
              <div style={{ fontSize: 12, color: "#8B93A3", marginTop: 2 }}>Taux d'occupation moyen</div>
            </div>
          </div>

          {rows.length === 0 ? (
            <p style={{ fontSize: 13, color: C.muted }}>Aucune personne dans votre périmètre pour le moment.</p>
          ) : (
            <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
                <thead>
                  <tr style={{ background: C.canvas, textAlign: "left" }}>
                    {["Agent", "Rôle", ...(vue === "jour" ? ["Connexion"] : []), "Production", ...pauseTypesList.map((pt) => pt.nom), "Occupation"].map((h) => (
                      <th key={h} style={{ padding: "10px 16px", color: C.muted, fontWeight: 600, fontSize: 11, textTransform: "uppercase", whiteSpace: "nowrap" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((a) => (
                    <tr key={a.id} style={{ borderTop: `1px solid ${C.borderSoft}` }}>
                      <td style={{ padding: "10px 16px", fontWeight: 500, whiteSpace: "nowrap" }}>{a.nom}</td>
                      <td style={{ padding: "10px 16px", textTransform: "capitalize", color: C.muted }}>{a.role}</td>
                      {vue === "jour" && (
                        <td className="mono" style={{ padding: "10px 16px", color: C.muted, whiteSpace: "nowrap" }}>
                          {a.heureConnexion ? new Date(a.heureConnexion).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" }) : "—"}
                        </td>
                      )}
                      <td className="mono" style={{ padding: "10px 16px", whiteSpace: "nowrap" }}>{fmtDuration(a.enProd)}</td>
                      {pauseTypesList.map((pt) => {
                        const t = a.byType[pt.code];
                        const seconds = t?.seconds || 0;
                        const capMin = pt.duree_max_minutes && pt.occurrences_max_jour ? pt.duree_max_minutes * pt.occurrences_max_jour : null;
                        const overCap = capMin && seconds / 60 > capMin;
                        return (
                          <td key={pt.code} className="mono" style={{ padding: "10px 16px", color: overCap ? C.red : C.muted, fontWeight: overCap ? 700 : 400, whiteSpace: "nowrap" }}>
                            {seconds > 0 ? fmtDuration(seconds) : "—"}
                          </td>
                        );
                      })}
                      <td style={{ padding: "10px 16px" }}>
                        <span style={{ background: `${occupationColor(a.occupation)}22`, color: occupationColor(a.occupation), padding: "2px 9px", borderRadius: 999, fontSize: 11, fontWeight: 700 }}>
                          {a.occupation === null ? "—" : `${Math.round(a.occupation * 100)}%`}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          <p style={{ fontSize: 11, color: C.mutedSoft, marginTop: 10 }}>
            La pause déjeuner n'est pas incluse dans la présence brute ni dans le taux d'occupation, mais reste visible ci-dessus et dans l'export.
          </p>
        </>
      )}
    </div>
  );
}


/* ---------------------------------- admin/superviseur : export des données traitées ---------------------------------- */

function ExportPanel({ accessToken }) {
  const todayStr = new Date().toISOString().slice(0, 10);
  const weekAgoStr = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString().slice(0, 10);

  const [dateStart, setDateStart] = useState(weekAgoStr);
  const [dateEnd, setDateEnd] = useState(todayStr);
  const [campagnes, setCampagnes] = useState(null);
  const [lots, setLots] = useState(null);
  const [campagneId, setCampagneId] = useState("");
  const [lotId, setLotId] = useState("");
  const [typesQualif, setTypesQualif] = useState(null);
  const [categorieFiltre, setCategorieFiltre] = useState("");
  const [motifFiltre, setMotifFiltre] = useState("");
  const [rows, setRows] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [exporting, setExporting] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const [c, l, tq] = await Promise.all([
          supaRest("campagnes?select=*&order=created_at.desc", { accessToken }),
          supaRest("lots?select=id,nom,campagne_id,cible_type,agent_id,groupe_id&order=created_at.desc", { accessToken }),
          supaRest("types_qualification?select=categorie,motif&order=categorie.asc,motif.asc", { accessToken }),
        ]);
        setCampagnes(c); setLots(l); setTypesQualif(tq);
      } catch (e) { setError(e.message); }
    })();
  }, [accessToken]);

  const lotsDisponibles = lots ? (campagneId ? lots.filter((l) => l.campagne_id === campagneId) : lots) : [];
  const categoriesDisponibles = typesQualif ? [...new Set(typesQualif.map((t) => t.categorie))] : [];
  const motifsDisponibles = typesQualif ? typesQualif.filter((t) => !categorieFiltre || t.categorie === categorieFiltre) : [];

  async function loadPreview() {
    setLoading(true); setError(null); setRows(null);
    try {
      const start = new Date(dateStart + "T00:00:00");
      const end = new Date(new Date(dateEnd + "T00:00:00").getTime() + 24 * 3600 * 1000);

      let lotIdsFiltre = null;
      if (lotId) lotIdsFiltre = [lotId];
      else if (campagneId) lotIdsFiltre = (lots || []).filter((l) => l.campagne_id === campagneId).map((l) => l.id);

      const qualifs = await supaRest(
        `qualifications?select=id,client_id,agent_id,commentaire,created_at,types_qualification(categorie,motif,est_contact,est_vente)&created_at=gte.${start.toISOString()}&created_at=lt.${end.toISOString()}&order=created_at.desc`,
        { accessToken }
      );
      if (qualifs.length === 0) { setRows([]); setLoading(false); return; }

      const clientIds = [...new Set(qualifs.map((q) => q.client_id))];
      const agentIds = [...new Set(qualifs.map((q) => q.agent_id).filter(Boolean))];

      const [clients, profils] = await Promise.all([
        fetchInChunks(`clients?select=id,numero_fiche,numero_box,nom,telephone,lot_id,lots(nom,campagne_id,campagnes(nom))&id=in.(`, clientIds, accessToken),
        agentIds.length > 0 ? fetchInChunks(`profils?select=id,nom&id=in.(`, agentIds, accessToken) : Promise.resolve([]),
      ]);

      const merged = qualifs.map((q) => {
        const c = clients.find((cl) => cl.id === q.client_id);
        return {
          ...q,
          client: c || null,
          agentNom: profils.find((p) => p.id === q.agent_id)?.nom || "—",
        };
      }).filter((r) => {
        if (lotIdsFiltre && !(r.client && lotIdsFiltre.includes(r.client.lot_id))) return false;
        if (categorieFiltre && r.types_qualification?.categorie !== categorieFiltre) return false;
        if (motifFiltre && r.types_qualification?.motif !== motifFiltre) return false;
        return true;
      });

      setRows(merged);
    } catch (e) { setError(e.message); } finally { setLoading(false); }
  }

  useEffect(() => { loadPreview(); }, [dateStart, dateEnd, campagneId, lotId, categorieFiltre, motifFiltre]); // eslint-disable-line

  function exportExcel() {
    setExporting(true);
    try {
      const data = rows.map((r) => ({
        "Date": new Date(r.created_at).toLocaleDateString("fr-FR"),
        "Heure": new Date(r.created_at).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" }),
        "Campagne": r.client?.lots?.campagnes?.nom || "",
        "Lot": r.client?.lots?.nom || "",
        "N° de box": r.client?.numero_box || "",
        "N° de fiche": r.client?.numero_fiche || "",
        "Client": r.client?.nom || "",
        "Téléphone": r.client?.telephone || "",
        "Agent": r.agentNom,
        "Catégorie": r.types_qualification?.categorie || "",
        "Motif": r.types_qualification?.motif || "",
        "Contact": r.types_qualification?.est_contact ? "Oui" : "Non",
        "Vente": r.types_qualification?.est_vente ? "Oui" : "Non",
        "Commentaire": r.commentaire || "",
      }));
      const ws = XLSX.utils.json_to_sheet(data);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Export");
      XLSX.writeFile(wb, `aureo_export_${dateStart}_${dateEnd}.xlsx`);
    } finally { setExporting(false); }
  }

  return (
    <div>
      <header className="mb-6">
        <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Export des données traitées</h1>
        <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Choisissez une période, puis affinez par campagne ou par lot.</p>
      </header>

      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18, marginBottom: 20, maxWidth: 760 }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: C.muted, marginBottom: 5, textTransform: "uppercase" }}>Du</div>
            <input type="date" value={dateStart} max={dateEnd} onChange={(e) => setDateStart(e.target.value)}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13 }} />
          </div>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: C.muted, marginBottom: 5, textTransform: "uppercase" }}>Au</div>
            <input type="date" value={dateEnd} min={dateStart} max={todayStr} onChange={(e) => setDateEnd(e.target.value)}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13 }} />
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: C.muted, marginBottom: 5, textTransform: "uppercase" }}>Campagne</div>
            <select value={campagneId} onChange={(e) => { setCampagneId(e.target.value); setLotId(""); }}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13, background: C.surface }}>
              <option value="">Toutes les campagnes</option>
              {(campagnes || []).map((c) => <option key={c.id} value={c.id}>{c.nom}</option>)}
            </select>
          </div>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: C.muted, marginBottom: 5, textTransform: "uppercase" }}>Lot</div>
            <select value={lotId} onChange={(e) => setLotId(e.target.value)}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13, background: C.surface }}>
              <option value="">{campagneId ? "Tous les lots de cette campagne" : "Tous les lots"}</option>
              {lotsDisponibles.map((l) => <option key={l.id} value={l.id}>{l.nom}</option>)}
            </select>
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginTop: 14 }}>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: C.muted, marginBottom: 5, textTransform: "uppercase" }}>Catégorie</div>
            <select value={categorieFiltre} onChange={(e) => { setCategorieFiltre(e.target.value); setMotifFiltre(""); }}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13, background: C.surface }}>
              <option value="">Toutes les catégories</option>
              {categoriesDisponibles.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: C.muted, marginBottom: 5, textTransform: "uppercase" }}>Qualification</div>
            <select value={motifFiltre} onChange={(e) => setMotifFiltre(e.target.value)}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13, background: C.surface }}>
              <option value="">{categorieFiltre ? "Tous les motifs de cette catégorie" : "Tous les motifs"}</option>
              {motifsDisponibles.map((t) => <option key={t.motif} value={t.motif}>{t.motif}</option>)}
            </select>
          </div>
        </div>
      </div>

      {error && <div className="mb-4"><ErrorBlock message={error} /></div>}

      <div className="flex items-center justify-between mb-4" style={{ maxWidth: 760 }}>
        <span style={{ fontSize: 13, color: C.muted }}>
          {loading ? "Recherche en cours…" : rows === null ? "" : `${rows.length} fiche${rows.length !== 1 ? "s" : ""} traitée${rows.length !== 1 ? "s" : ""} sur la période`}
        </span>
        <button onClick={exportExcel} disabled={!rows || rows.length === 0 || exporting}
          style={{ display: "flex", alignItems: "center", gap: 6, background: C.ink, color: "#fff", border: "none", borderRadius: 8, padding: "9px 16px", fontSize: 12.5, fontWeight: 600 }}>
          {exporting ? <Loader2 size={13} className="animate-spin" /> : <FileSpreadsheet size={13} />} Exporter Excel
        </button>
      </div>

      {rows && rows.length > 0 && (
        <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "auto", maxHeight: 460 }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
            <thead>
              <tr style={{ background: C.canvas, textAlign: "left" }}>
                {["Date", "Client", "Agent", "Catégorie", "Motif", "Contact", "Vente"].map((h) => (
                  <th key={h} style={{ padding: "9px 14px", color: C.muted, fontWeight: 600, fontSize: 10.5, textTransform: "uppercase", whiteSpace: "nowrap" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.slice(0, 200).map((r) => (
                <tr key={r.id} style={{ borderTop: `1px solid ${C.borderSoft}` }}>
                  <td className="mono" style={{ padding: "8px 14px", color: C.mutedSoft, whiteSpace: "nowrap" }}>{new Date(r.created_at).toLocaleDateString("fr-FR")}</td>
                  <td style={{ padding: "8px 14px", fontWeight: 500 }}>{r.client?.nom || "—"}</td>
                  <td style={{ padding: "8px 14px", color: C.muted }}>{r.agentNom}</td>
                  <td style={{ padding: "8px 14px" }}>{r.types_qualification?.categorie}</td>
                  <td style={{ padding: "8px 14px" }}>{r.types_qualification?.motif}</td>
                  <td style={{ padding: "8px 14px" }}>{r.types_qualification?.est_contact ? "Oui" : "Non"}</td>
                  <td style={{ padding: "8px 14px" }}>{r.types_qualification?.est_vente ? "Oui" : "Non"}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {rows.length > 200 && (
            <p style={{ fontSize: 11, color: C.mutedSoft, padding: "10px 14px" }}>Aperçu limité à 200 lignes — l'export Excel contient l'intégralité des {rows.length} fiches.</p>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------- admin : file d'attente ---------------------------------- */

function Queue({ accessToken, refreshFlag, bump }) {
  const [clients, setClients] = useState(null);
  const [error, setError] = useState(null);
  const [, forceTick] = useState(0);

  const load = useCallback(async () => {
    try {
      const rows = await supaRest("clients?select=*&order=created_at.desc&limit=100", { accessToken });
      setClients(rows);
    } catch (e) { setError(e.message); }
  }, [accessToken]);

  useEffect(() => { load(); }, [load, refreshFlag]);
  useEffect(() => { const t = setInterval(load, 30000); return () => clearInterval(t); }, [load]);
  useEffect(() => { const t = setInterval(() => forceTick((n) => n + 1), 1000); return () => clearInterval(t); }, []);

  if (error) return <ErrorBlock message={error} />;
  if (!clients) return <CenterLoader />;

  const order = { en_cours: 0, disponible: 1, planifie: 2, archive: 3 };
  const sorted = [...clients].sort((a, b) => order[a.statut] - order[b.statut]);

  return (
    <div>
      <header className="mb-5">
        <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>File d'attente</h1>
        <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>
          Les fiches « planifiées » repassent automatiquement en disponible via la tâche planifiée (pg_cron, toutes les 5 minutes).
        </p>
      </header>

      <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
          <thead>
            <tr style={{ background: C.canvas, textAlign: "left" }}>
              {["N°", "Client", "Statut", "Échéance"].map((h) => (
                <th key={h} style={{ padding: "10px 16px", color: C.muted, fontWeight: 600, fontSize: 11, textTransform: "uppercase", letterSpacing: "0.03em" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sorted.map((c) => {
              const meta = STATUS_META[c.statut];
              const enRetard = c.statut === "planifie" && c.visible_apres && new Date(c.visible_apres).getTime() <= Date.now();
              return (
                <tr key={c.id} style={{ borderTop: `1px solid ${C.borderSoft}` }}>
                  <td className="mono" style={{ padding: "10px 16px", color: C.mutedSoft }}>{c.numero_fiche}</td>
                  <td style={{ padding: "10px 16px", fontWeight: 500 }}>{c.nom}</td>
                  <td style={{ padding: "10px 16px" }}>
                    <span style={{ background: meta.soft, color: meta.color, padding: "2px 9px", borderRadius: 999, fontSize: 11, fontWeight: 600 }}>{meta.label}</span>
                  </td>
                  <td className="mono" style={{ padding: "10px 16px", color: enRetard ? C.red : C.mutedSoft, fontWeight: enRetard ? 700 : 400 }}>
                    {c.statut === "planifie" && c.visible_apres ? fmtCountdown(new Date(c.visible_apres).getTime() - Date.now()) : "—"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ---------------------------------- admin : import ---------------------------------- */

function ImportPanel({ accessToken, bump }) {
  const [summary, setSummary] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const inputRef = useRef(null);

  const [campagnes, setCampagnes] = useState(null);
  const [lots, setLots] = useState(null);
  const [groupes, setGroupes] = useState(null);
  const [agents, setAgents] = useState(null);

  const [campagneId, setCampagneId] = useState("");
  const [lotId, setLotId] = useState("");

  const [showNewCampagne, setShowNewCampagne] = useState(false);
  const [newCampagneNom, setNewCampagneNom] = useState("");
  const [creatingCampagne, setCreatingCampagne] = useState(false);

  const [showNewLot, setShowNewLot] = useState(false);
  const [newLotNom, setNewLotNom] = useState("");
  const [newLotCibleType, setNewLotCibleType] = useState("agent");
  const [newLotCibleId, setNewLotCibleId] = useState("");
  const [creatingLot, setCreatingLot] = useState(false);

  const loadRefData = useCallback(async () => {
    try {
      const [c, l, g, a] = await Promise.all([
        supaRest("campagnes?select=*&actif=eq.true&order=created_at.desc", { accessToken }),
        supaRest("lots?select=*&order=created_at.desc", { accessToken }),
        supaRest("groupes_agents?select=*&order=nom.asc", { accessToken }),
        supaRest("profils?select=id,nom&role=in.(agent,coach)&order=nom.asc", { accessToken }),
      ]);
      setCampagnes(c); setLots(l); setGroupes(g); setAgents(a);
      if (c.length > 0 && !campagneId) setCampagneId(c[0].id);
    } catch (e) { setError(e.message); }
  }, [accessToken]); // eslint-disable-line

  useEffect(() => { loadRefData(); }, [loadRefData]);

  // Lots appartenant à la campagne sélectionnée
  const lotsDeLaCampagne = useMemo(
    () => (lots || []).filter((l) => l.campagne_id === campagneId),
    [lots, campagneId]
  );

  useEffect(() => {
    // si la campagne change, on repart sur le premier lot dispo (ou aucun)
    if (lotsDeLaCampagne.length > 0) setLotId(lotsDeLaCampagne[0].id);
    else setLotId("");
  }, [campagneId]); // eslint-disable-line

  async function createCampagne() {
    const nom = newCampagneNom.trim();
    if (!nom) return;
    setCreatingCampagne(true); setError(null);
    try {
      const [row] = await supaRest("campagnes", { method: "POST", accessToken, body: { nom } });
      setNewCampagneNom(""); setShowNewCampagne(false);
      await loadRefData();
      setCampagneId(row.id);
    } catch (e) { setError(e.message); } finally { setCreatingCampagne(false); }
  }

  async function createLot() {
    const nom = newLotNom.trim();
    if (!nom || !campagneId || !newLotCibleId) return;
    setCreatingLot(true); setError(null);
    try {
      const body = newLotCibleType === "agent"
        ? { campagne_id: campagneId, nom, cible_type: "agent", agent_id: newLotCibleId }
        : { campagne_id: campagneId, nom, cible_type: "groupe", groupe_id: newLotCibleId };
      const [row] = await supaRest("lots", { method: "POST", accessToken, body });
      await rpc("admin_ajouter_cible_lot", accessToken, { p_lot_id: row.id, p_cible_type: newLotCibleType, p_cible_id: newLotCibleId });
      setNewLotNom(""); setNewLotCibleId(""); setShowNewLot(false);
      await loadRefData();
      setLotId(row.id);
    } catch (e) { setError(e.message); } finally { setCreatingLot(false); }
  }

  async function finalizeImport(rows, fileName) {
    if (!lotId) { setError("Sélectionnez ou créez un lot avant d'importer. Une fiche sans lot ne sera jamais distribuée."); return; }
    const payload = rowsToClients(rows, lotId);
    if (payload.length === 0) { setError("Aucune ligne exploitable trouvée dans ce fichier."); return; }
    setBusy(true);
    try {
      // Détection des doublons : un client déjà présent en base (n'importe
      // quelle campagne) ne doit jamais être réimporté une seconde fois —
      // même principe que la création manuelle depuis le poste de travail.
      const telephones = [...new Set(payload.map((p) => p.telephone).filter(Boolean))];
      const boxes = [...new Set(payload.map((p) => p.numero_box).filter(Boolean))];
      const [parTelephone, parBox] = await Promise.all([
        fetchInChunks("clients?select=telephone&telephone=in.(", telephones, accessToken),
        fetchInChunks("clients?select=numero_box&numero_box=in.(", boxes, accessToken),
      ]);
      const telephonesExistants = new Set(parTelephone.map((c) => c.telephone));
      const boxesExistants = new Set(parBox.map((c) => c.numero_box));

      const aInserer = [];
      let doublons = 0;
      for (const p of payload) {
        const dejaLa = (p.telephone && telephonesExistants.has(p.telephone)) || (p.numero_box && boxesExistants.has(p.numero_box));
        if (dejaLa) doublons++;
        else aInserer.push(p);
      }

      if (aInserer.length > 0) {
        await supaRest("clients", { method: "POST", accessToken, body: aInserer });
      }
      setSummary({ fileName, count: aInserer.length, doublons });
      setError(null);
      bump();
    } catch (e) { setError(e.message); } finally { setBusy(false); }
  }

  function handleFile(file) {
    if (!file) return;
    if (!lotId) { setError("Sélectionnez ou créez un lot avant d'importer."); return; }
    const ext = file.name.split(".").pop().toLowerCase();
    if (ext === "csv") {
      Papa.parse(file, { header: true, skipEmptyLines: true, complete: (res) => finalizeImport(res.data, file.name), error: () => setError("Impossible de lire ce fichier CSV.") });
    } else if (ext === "xlsx" || ext === "xls") {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const wb = XLSX.read(e.target.result, { type: "array" });
          const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: "" });
          finalizeImport(rows, file.name);
        } catch { setError("Impossible de lire ce fichier Excel."); }
      };
      reader.readAsArrayBuffer(file);
    } else {
      setError("Format non pris en charge. Utilisez un fichier .csv ou .xlsx.");
    }
  }

  const cibleOptions = newLotCibleType === "agent" ? (agents || []) : (groupes || []);

  function downloadTemplate() {
    const headers = ["Numéro de box", "Nom", "Numéro de contact 1", "Numéro MTN", "Type de segment", "Commune", "Email", "Note"];
    const ws = XLSX.utils.aoa_to_sheet([headers]);
    ws["!cols"] = headers.map(() => ({ wch: 22 }));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Fiches");
    XLSX.writeFile(wb, "aureo_modele_import.xlsx");
  }

  return (
    <div>
      <header className="mb-6 flex items-start justify-between">
        <div>
          <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Import de fiches</h1>
          <p style={{ fontSize: 13, color: C.muted, marginTop: 3, maxWidth: 560 }}>
            Colonnes reconnues automatiquement : numéro de box, nom, contact 1, numéro MTN, segment, commune, email, note.
            Chaque import constitue un <strong>lot</strong>, rattaché à une campagne et attribué à un agent ou un groupe.
          </p>
        </div>
        <button onClick={downloadTemplate}
          style={{ display: "flex", alignItems: "center", gap: 6, background: C.surface, border: `1px solid ${C.border}`, borderRadius: 8, padding: "9px 14px", fontSize: 12.5, fontWeight: 600, color: C.text, whiteSpace: "nowrap", flexShrink: 0 }}>
          <FileSpreadsheet size={13} color={C.teal} /> Télécharger le modèle
        </button>
      </header>

      {(campagnes === null || lots === null || groupes === null || agents === null) ? (
        <CenterLoader />
      ) : (
        <>
          {/* Étape 1 — Campagne */}
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 16, marginBottom: 14, maxWidth: 560 }}>
            <div style={{ fontSize: 11.5, fontWeight: 600, color: C.muted, marginBottom: 8, textTransform: "uppercase", letterSpacing: "0.03em" }}>1 · Campagne</div>
            {campagnes.length === 0 && !showNewCampagne ? (
              <div className="flex items-center justify-between">
                <span style={{ fontSize: 12.5, color: C.muted }}>Aucune campagne pour le moment.</span>
                <button onClick={() => setShowNewCampagne(true)} style={{ display: "flex", alignItems: "center", gap: 6, background: C.ink, color: "#fff", border: "none", borderRadius: 7, padding: "7px 12px", fontSize: 12, fontWeight: 600 }}>
                  <Plus size={12} /> Nouvelle campagne
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                {!showNewCampagne ? (
                  <>
                    <select value={campagneId} onChange={(e) => setCampagneId(e.target.value)}
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5, background: C.surface }}>
                      {campagnes.map((c) => <option key={c.id} value={c.id}>{c.nom}</option>)}
                    </select>
                    <button onClick={() => setShowNewCampagne(true)} title="Nouvelle campagne"
                      style={{ background: C.canvas, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px" }}>
                      <Plus size={13} color={C.muted} />
                    </button>
                  </>
                ) : (
                  <>
                    <input value={newCampagneNom} onChange={(e) => setNewCampagneNom(e.target.value)} placeholder="Nom de la nouvelle campagne…" autoFocus
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
                    <button onClick={createCampagne} disabled={creatingCampagne}
                      style={{ background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "8px 12px", fontSize: 12, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
                      {creatingCampagne && <Loader2 size={11} className="animate-spin" />} Créer
                    </button>
                    {campagnes.length > 0 && (
                      <button onClick={() => setShowNewCampagne(false)} style={{ background: "none", border: "none", color: C.mutedSoft, padding: 6 }}>
                        <X size={14} />
                      </button>
                    )}
                  </>
                )}
              </div>
            )}
          </div>

          {/* Étape 2 — Lot (sous-ensemble de fiches, attribué à un agent ou un groupe) */}
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 16, marginBottom: 20, maxWidth: 560, opacity: campagneId ? 1 : 0.5 }}>
            <div style={{ fontSize: 11.5, fontWeight: 600, color: C.muted, marginBottom: 8, textTransform: "uppercase", letterSpacing: "0.03em" }}>2 · Lot (attribution)</div>
            {!campagneId ? (
              <p style={{ fontSize: 12.5, color: C.mutedSoft }}>Choisissez d'abord une campagne.</p>
            ) : lotsDeLaCampagne.length === 0 && !showNewLot ? (
              <div className="flex items-center justify-between">
                <span style={{ fontSize: 12.5, color: C.muted }}>Aucun lot dans cette campagne.</span>
                <button onClick={() => setShowNewLot(true)} style={{ display: "flex", alignItems: "center", gap: 6, background: C.ink, color: "#fff", border: "none", borderRadius: 7, padding: "7px 12px", fontSize: 12, fontWeight: 600 }}>
                  <Plus size={12} /> Nouveau lot
                </button>
              </div>
            ) : !showNewLot ? (
              <div className="flex items-center gap-2">
                <select value={lotId} onChange={(e) => setLotId(e.target.value)}
                  style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5, background: C.surface }}>
                  {lotsDeLaCampagne.map((l) => {
                    const cible = l.cible_type === "agent" ? agents.find((a) => a.id === l.agent_id)?.nom : groupes.find((g) => g.id === l.groupe_id)?.nom;
                    return <option key={l.id} value={l.id}>{l.nom} — {cible || "?"}</option>;
                  })}
                </select>
                <button onClick={() => setShowNewLot(true)} title="Nouveau lot"
                  style={{ background: C.canvas, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px" }}>
                  <Plus size={13} color={C.muted} />
                </button>
              </div>
            ) : (
              <div className="flex flex-col gap-2">
                <input value={newLotNom} onChange={(e) => setNewLotNom(e.target.value)} placeholder="Nom du lot (ex: Lot 1 — Zone Nord)…" autoFocus
                  style={{ border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
                <div className="flex items-center gap-2">
                  <div style={{ background: C.canvas, borderRadius: 7, padding: 3 }} className="flex gap-1">
                    {[{ id: "agent", label: "Agent" }, { id: "groupe", label: "Groupe" }].map((t) => (
                      <button key={t.id} onClick={() => { setNewLotCibleType(t.id); setNewLotCibleId(""); }}
                        style={{ padding: "6px 12px", borderRadius: 5, border: "none", background: newLotCibleType === t.id ? C.ink : "transparent", color: newLotCibleType === t.id ? "#fff" : C.muted, fontSize: 12, fontWeight: 600 }}>
                        {t.label}
                      </button>
                    ))}
                  </div>
                  <select value={newLotCibleId} onChange={(e) => setNewLotCibleId(e.target.value)}
                    style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5, background: C.surface }}>
                    <option value="">Choisir {newLotCibleType === "agent" ? "un agent" : "un groupe"}…</option>
                    {cibleOptions.map((o) => <option key={o.id} value={o.id}>{o.nom}</option>)}
                  </select>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={createLot} disabled={creatingLot || !newLotNom.trim() || !newLotCibleId}
                    style={{ flex: 1, background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "8px 0", fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                    {creatingLot && <Loader2 size={11} className="animate-spin" />} Créer le lot
                  </button>
                  {lotsDeLaCampagne.length > 0 && (
                    <button onClick={() => setShowNewLot(false)} style={{ background: "none", border: "none", color: C.mutedSoft, padding: 6 }}>
                      <X size={14} />
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Étape 3 — Fichier */}
          <div onDragOver={(e) => e.preventDefault()} onDrop={(e) => { e.preventDefault(); handleFile(e.dataTransfer.files[0]); }} onClick={() => lotId && inputRef.current?.click()}
            style={{ background: C.surface, border: `2px dashed ${C.border}`, borderRadius: 14, padding: "48px 24px", textAlign: "center", cursor: lotId ? "pointer" : "not-allowed", maxWidth: 520, opacity: lotId ? 1 : 0.55 }}>
            {busy ? <Loader2 size={26} className="animate-spin" style={{ margin: "0 auto 12px" }} color={C.teal} /> : <FileSpreadsheet size={26} color={C.teal} style={{ margin: "0 auto 12px" }} />}
            <div style={{ fontSize: 14, fontWeight: 600 }}>Déposez un fichier .csv ou .xlsx</div>
            <div style={{ fontSize: 12, color: C.muted, marginTop: 4 }}>ou cliquez pour parcourir</div>
            <input ref={inputRef} type="file" accept=".csv,.xlsx,.xls" style={{ display: "none" }} onChange={(e) => handleFile(e.target.files[0])} />
          </div>

          {summary && (
            <div className="flex flex-col gap-1.5 mt-4" style={{ maxWidth: 520 }}>
              <div className="flex items-center gap-2" style={{ background: C.greenSoft, color: C.green, borderRadius: 9, padding: "10px 14px", fontSize: 13, fontWeight: 500 }}>
                <CheckCircle2 size={15} /> {summary.count} fiche(s) importée(s) depuis « {summary.fileName} ».
              </div>
              {summary.doublons > 0 && (
                <div className="flex items-center gap-2" style={{ background: C.amberSoft, color: C.ink, borderRadius: 9, padding: "10px 14px", fontSize: 12.5 }}>
                  <AlertTriangle size={14} color={C.amber} />
                  {summary.doublons} ligne{summary.doublons !== 1 ? "s" : ""} ignorée{summary.doublons !== 1 ? "s" : ""} — numéro de téléphone ou de box déjà présent en base.
                </div>
              )}
            </div>
          )}
          {error && <div className="mt-4"><ErrorBlock message={error} /></div>}
        </>
      )}
    </div>
  );
}

/* ---------------------------------- admin : campagnes & lots ---------------------------------- */

function CampaignsPanel({ accessToken }) {
  const [subTab, setSubTab] = useState("campagnes"); // campagnes | groupes
  const [campagnes, setCampagnes] = useState(null);
  const [lots, setLots] = useState(null);
  const [lotsCibles, setLotsCibles] = useState(null);
  const [groupes, setGroupes] = useState(null);
  const [agents, setAgents] = useState(null);
  const [membres, setMembres] = useState(null);
  const [error, setError] = useState(null);
  const [selectedCampagne, setSelectedCampagne] = useState(null);
  const [selectedGroupe, setSelectedGroupe] = useState(null);

  const loadAll = useCallback(async () => {
    try {
      const [c, l, lc, g, a, m] = await Promise.all([
        supaRest("campagnes?select=*&order=created_at.desc", { accessToken }),
        supaRest("lots?select=*&order=created_at.desc", { accessToken }),
        supaRest("lots_cibles?select=*", { accessToken }),
        supaRest("groupes_agents?select=*&order=created_at.desc", { accessToken }),
        supaRest("profils?select=id,nom&role=in.(agent,coach)&order=nom.asc", { accessToken }),
        supaRest("groupes_agents_membres?select=*", { accessToken }),
      ]);
      setCampagnes(c); setLots(l); setLotsCibles(lc); setGroupes(g); setAgents(a); setMembres(m);
    } catch (e) { setError(e.message); }
  }, [accessToken]);

  useEffect(() => { loadAll(); }, [loadAll]);

  if (error) return <ErrorBlock message={error} />;
  if (!campagnes || !lots || !lotsCibles || !groupes || !agents || !membres) return <CenterLoader />;

  return (
    <div>
      <header className="mb-6 flex items-end justify-between">
        <div>
          <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Campagnes</h1>
          <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>
            Une campagne regroupe des lots de fiches ; chaque lot peut être partagé par plusieurs agents ou groupes.
          </p>
        </div>
        <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10, padding: 4 }} className="flex gap-1">
          <button onClick={() => setSubTab("campagnes")}
            style={{ padding: "7px 14px", borderRadius: 7, border: "none", background: subTab === "campagnes" ? C.ink : "transparent", color: subTab === "campagnes" ? "#fff" : C.muted, fontSize: 12.5, fontWeight: 600 }}>
            Campagnes
          </button>
          <button onClick={() => setSubTab("groupes")}
            style={{ padding: "7px 14px", borderRadius: 7, border: "none", background: subTab === "groupes" ? C.ink : "transparent", color: subTab === "groupes" ? "#fff" : C.muted, fontSize: 12.5, fontWeight: 600 }}>
            Groupes d'agents
          </button>
        </div>
      </header>

      {subTab === "campagnes" ? (
        <CampagnesTab
          accessToken={accessToken} campagnes={campagnes} lots={lots} lotsCibles={lotsCibles} groupes={groupes} agents={agents}
          selected={selectedCampagne} setSelected={setSelectedCampagne} reload={loadAll}
        />
      ) : (
        <GroupesTab
          accessToken={accessToken} groupes={groupes} agents={agents} membres={membres}
          selected={selectedGroupe} setSelected={setSelectedGroupe} reload={loadAll}
        />
      )}
    </div>
  );
}

function CampagnesTab({ accessToken, campagnes, lots, lotsCibles, groupes, agents, selected, setSelected, reload }) {
  const [showNew, setShowNew] = useState(false);
  const [nom, setNom] = useState("");
  const [description, setDescription] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);

  const [editingNom, setEditingNom] = useState(false);
  const [editNomValue, setEditNomValue] = useState("");
  const [savingNom, setSavingNom] = useState(false);

  const [fichesParLot, setFichesParLot] = useState({});

  const [showAttach, setShowAttach] = useState(false);
  const [attachNom, setAttachNom] = useState("");
  const [attachCibleType, setAttachCibleType] = useState("agent");
  const [attachCibleId, setAttachCibleId] = useState("");
  const [attaching, setAttaching] = useState(false);

  const [confirmDeleteLotId, setConfirmDeleteLotId] = useState(null);
  const [deletingLotId, setDeletingLotId] = useState(null);
  const [deleteInfo, setDeleteInfo] = useState(null);

  const [addingCibleLotId, setAddingCibleLotId] = useState(null);
  const [newCibleType, setNewCibleType] = useState("agent");
  const [newCibleId, setNewCibleId] = useState("");
  const [savingCible, setSavingCible] = useState(false);
  const [removingCibleId, setRemovingCibleId] = useState(null);

  async function deleteLot(lotId) {
    setDeletingLotId(lotId); setError(null); setDeleteInfo(null);
    try {
      const nbSupprimees = await rpc("admin_delete_lot", accessToken, { p_lot_id: lotId });
      setDeleteInfo({ nbSupprimees });
      setConfirmDeleteLotId(null);
      reload();
    } catch (e) { setError(e.message); } finally { setDeletingLotId(null); }
  }

  function startAddCible(l) {
    setAddingCibleLotId(l.id);
    setNewCibleType("agent");
    setNewCibleId("");
    setConfirmDeleteLotId(null);
  }

  async function addCible(lotId) {
    if (!newCibleId) return;
    setSavingCible(true); setError(null);
    try {
      await rpc("admin_ajouter_cible_lot", accessToken, { p_lot_id: lotId, p_cible_type: newCibleType, p_cible_id: newCibleId });
      setAddingCibleLotId(null);
      reload();
    } catch (e) { setError(e.message); } finally { setSavingCible(false); }
  }

  async function removeCible(lotCibleId) {
    setRemovingCibleId(lotCibleId); setError(null);
    try {
      await rpc("admin_retirer_cible_lot", accessToken, { p_lot_cible_id: lotCibleId });
      reload();
    } catch (e) { setError(e.message); } finally { setRemovingCibleId(null); }
  }

  async function createCampagne() {
    if (!nom.trim()) return;
    setBusy(true); setError(null);
    try {
      await supaRest("campagnes", { method: "POST", accessToken, body: { nom: nom.trim(), description: description.trim() || null } });
      setNom(""); setDescription(""); setShowNew(false);
      reload();
    } catch (e) { setError(e.message); } finally { setBusy(false); }
  }

  async function saveNom(campagneId) {
    const val = editNomValue.trim();
    if (!val) return;
    setSavingNom(true); setError(null);
    try {
      // Renommer la campagne n'affecte jamais la distribution : les lots référencent
      // campagne_id (identifiant stable), jamais le libellé "nom".
      await supaRest(`campagnes?id=eq.${campagneId}`, { method: "PATCH", accessToken, body: { nom: val } });
      setEditingNom(false);
      reload();
    } catch (e) { setError(e.message); } finally { setSavingNom(false); }
  }

  async function attachLot(campagneId) {
    if (!attachNom.trim() || !attachCibleId) return;
    setAttaching(true); setError(null);
    try {
      const body = attachCibleType === "agent"
        ? { campagne_id: campagneId, nom: attachNom.trim(), cible_type: "agent", agent_id: attachCibleId }
        : { campagne_id: campagneId, nom: attachNom.trim(), cible_type: "groupe", groupe_id: attachCibleId };
      const [row] = await supaRest("lots", { method: "POST", accessToken, body });
      await rpc("admin_ajouter_cible_lot", accessToken, { p_lot_id: row.id, p_cible_type: attachCibleType, p_cible_id: attachCibleId });
      setAttachNom(""); setAttachCibleId(""); setShowAttach(false);
      reload();
    } catch (e) { setError(e.message); } finally { setAttaching(false); }
  }

  const current = campagnes.find((c) => c.id === selected) || null;
  const lotsCourants = current ? lots.filter((l) => l.campagne_id === current.id) : [];
  const attachCibleOptions = attachCibleType === "agent" ? agents : groupes;

  useEffect(() => {
    if (!current) return;
    (async () => {
      try {
        const rows = await supaRest("vue_compte_fiches_par_lot?select=*", { accessToken });
        const counts = {};
        lotsCourants.forEach((l) => { counts[l.id] = rows.find((r) => r.lot_id === l.id)?.total || 0; });
        setFichesParLot(counts);
      } catch {
        const counts = {};
        lotsCourants.forEach((l) => { counts[l.id] = null; });
        setFichesParLot(counts);
      }
    })();
  }, [current?.id, lots.length]); // eslint-disable-line

  return (
    <div style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: 20 }}>
      <div>
        <button onClick={() => setShowNew((v) => !v)}
          style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, background: C.ink, color: "#fff", border: "none", borderRadius: 9, padding: "10px 0", fontSize: 13, fontWeight: 600, marginBottom: 12 }}>
          <Plus size={14} /> Nouvelle campagne
        </button>

        {showNew && (
          <div style={{ background: C.surface, border: `1.5px solid ${C.ink}`, borderRadius: 10, padding: 12, marginBottom: 12 }}>
            <input value={nom} onChange={(e) => setNom(e.target.value)} placeholder="Nom de la campagne…" autoFocus
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, marginBottom: 6 }} />
            <textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Description (facultatif)…" rows={2}
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12, resize: "none", marginBottom: 8 }} />
            <button onClick={createCampagne} disabled={busy}
              style={{ width: "100%", background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "8px 0", fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
              {busy && <Loader2 size={12} className="animate-spin" />} Créer
            </button>
          </div>
        )}

        {error && <div className="mb-3"><ErrorBlock message={error} /></div>}

        <div className="flex flex-col gap-2">
          {campagnes.length === 0 && <p style={{ fontSize: 12.5, color: C.muted }}>Aucune campagne créée.</p>}
          {campagnes.map((c) => {
            const nbLots = lots.filter((l) => l.campagne_id === c.id).length;
            const isActive = selected === c.id;
            return (
              <button key={c.id} onClick={() => { setSelected(c.id); setEditingNom(false); setShowAttach(false); }}
                style={{ textAlign: "left", background: isActive ? C.ink : C.surface, color: isActive ? "#fff" : C.text, border: `1px solid ${isActive ? C.ink : C.border}`, borderRadius: 10, padding: "12px 14px" }}>
                <div style={{ fontSize: 13, fontWeight: 600 }}>{c.nom}</div>
                <div style={{ fontSize: 11, color: isActive ? "#A6ADBA" : C.muted, marginTop: 2 }}>
                  {nbLots} lot{nbLots !== 1 ? "s" : ""}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div>
        {!current ? (
          <div style={{ background: C.surface, border: `1px dashed ${C.border}`, borderRadius: 12, padding: 40, textAlign: "center", color: C.muted, fontSize: 13 }}>
            Sélectionnez une campagne pour la rattacher à des agents ou groupes.
          </div>
        ) : (
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 20 }}>
            <div className="flex items-center gap-2">
              {!editingNom ? (
                <>
                  <h3 className="disp" style={{ fontSize: 16, fontWeight: 700 }}>{current.nom}</h3>
                  <button onClick={() => { setEditingNom(true); setEditNomValue(current.nom); }}
                    title="Renommer" style={{ background: "none", border: "none", padding: 2 }}>
                    <ListChecks size={13} color={C.mutedSoft} />
                  </button>
                </>
              ) : (
                <div className="flex items-center gap-2" style={{ flex: 1 }}>
                  <input value={editNomValue} onChange={(e) => setEditNomValue(e.target.value)} autoFocus
                    style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "6px 9px", fontSize: 13.5, fontWeight: 600 }} />
                  <button onClick={() => saveNom(current.id)} disabled={savingNom}
                    style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 7, padding: "6px 10px" }}>
                    {savingNom ? <Loader2 size={12} className="animate-spin" /> : <Check size={12} />}
                  </button>
                  <button onClick={() => setEditingNom(false)} style={{ background: "none", border: "none", color: C.mutedSoft, padding: 4 }}>
                    <X size={14} />
                  </button>
                </div>
              )}
            </div>
            {current.description && <p style={{ fontSize: 12.5, color: C.muted, marginTop: 3 }}>{current.description}</p>}
            <p style={{ fontSize: 11, color: C.mutedSoft, marginTop: 4 }}>
              Renommer une campagne n'a aucun effet sur la distribution : chaque lot reste rattaché par identifiant, pas par nom.
            </p>
            {error && <div className="mt-3"><ErrorBlock message={error} /></div>}
            {deleteInfo && (
              <div className="flex items-center gap-2 mt-3" style={{ background: C.greenSoft, color: C.green, borderRadius: 8, padding: "8px 12px", fontSize: 12 }}>
                <CheckCircle2 size={13} /> Lot supprimé ({deleteInfo.nbSupprimees} fiche{deleteInfo.nbSupprimees !== 1 ? "s" : ""} effacée{deleteInfo.nbSupprimees !== 1 ? "s" : ""}).
              </div>
            )}

            <div style={{ marginTop: 20, paddingTop: 16, borderTop: `1px dashed ${C.border}` }}>
              <div className="flex items-center justify-between" style={{ marginBottom: 10 }}>
                <div className="flex items-center gap-1.5" style={{ fontSize: 11.5, fontWeight: 600, color: C.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}>
                  <ListChecks size={13} /> Lots de cette campagne
                </div>
                <button onClick={() => setShowAttach((v) => !v)}
                  style={{ display: "flex", alignItems: "center", gap: 5, background: C.canvas, border: `1px solid ${C.border}`, borderRadius: 7, padding: "5px 10px", fontSize: 11.5, fontWeight: 600, color: C.text }}>
                  <Plus size={11} /> Rattacher à un agent/groupe
                </button>
              </div>

              {showAttach && (
                <div style={{ background: C.canvas, borderRadius: 8, padding: 12, marginBottom: 12 }}>
                  <input value={attachNom} onChange={(e) => setAttachNom(e.target.value)} placeholder="Nom du lot (ex: Lot 3 — Renfort)…" autoFocus
                    style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, marginBottom: 8 }} />
                  <div className="flex items-center gap-2">
                    <div style={{ background: C.surface, borderRadius: 7, padding: 3, border: `1px solid ${C.border}` }} className="flex gap-1">
                      {[{ id: "agent", label: "Agent" }, { id: "groupe", label: "Groupe" }].map((t) => (
                        <button key={t.id} onClick={() => { setAttachCibleType(t.id); setAttachCibleId(""); }}
                          style={{ padding: "6px 12px", borderRadius: 5, border: "none", background: attachCibleType === t.id ? C.ink : "transparent", color: attachCibleType === t.id ? "#fff" : C.muted, fontSize: 12, fontWeight: 600 }}>
                          {t.label}
                        </button>
                      ))}
                    </div>
                    <select value={attachCibleId} onChange={(e) => setAttachCibleId(e.target.value)}
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, background: C.surface }}>
                      <option value="">Choisir {attachCibleType === "agent" ? "un agent" : "un groupe"}…</option>
                      {attachCibleOptions.map((o) => <option key={o.id} value={o.id}>{o.nom}</option>)}
                    </select>
                    <button onClick={() => attachLot(current.id)} disabled={attaching || !attachNom.trim() || !attachCibleId}
                      style={{ background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "7px 14px", fontSize: 12, fontWeight: 700, display: "flex", alignItems: "center", gap: 6, whiteSpace: "nowrap" }}>
                      {attaching && <Loader2 size={11} className="animate-spin" />} Rattacher
                    </button>
                  </div>
                  <p style={{ fontSize: 10.5, color: C.mutedSoft, marginTop: 6 }}>
                    Crée un lot vide, prêt à recevoir des fiches lors d'un prochain import.
                  </p>
                </div>
              )}

              {lotsCourants.length === 0 ? (
                <p style={{ fontSize: 12.5, color: C.mutedSoft }}>Aucun lot pour le moment.</p>
              ) : (
                <div className="flex flex-col gap-2">
                  {lotsCourants.map((l) => {
                    const cibles = lotsCibles.filter((lc) => lc.lot_id === l.id);
                    const nbFiches = fichesParLot[l.id];
                    const confirming = confirmDeleteLotId === l.id;
                    const addingCible = addingCibleLotId === l.id;
                    const newCibleOptions = newCibleType === "agent" ? agents : groupes;
                    return (
                      <div key={l.id} style={{ padding: "10px 12px", background: confirming ? C.redSoft : C.canvas, borderRadius: 8 }}>
                        <div className="flex items-center justify-between">
                          <div style={{ flex: 1 }}>
                            <div style={{ fontSize: 12.5, fontWeight: 600, marginBottom: 5 }}>{l.nom}</div>
                            <div className="flex flex-wrap items-center gap-1.5">
                              {cibles.length === 0 ? (
                                <span style={{ fontSize: 11, color: C.mutedSoft, fontStyle: "italic" }}>Aucune cible — personne ne recevra ces fiches</span>
                              ) : cibles.map((c) => {
                                const nomCible = c.cible_type === "agent" ? agents.find((a) => a.id === c.agent_id)?.nom : groupes.find((g) => g.id === c.groupe_id)?.nom;
                                return (
                                  <span key={c.id} className="flex items-center gap-1.5" style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 999, padding: "3px 8px 3px 10px", fontSize: 11 }}>
                                    {c.cible_type === "agent" ? <UserCircle2 size={10} /> : <UsersRound size={10} />}
                                    {nomCible || "?"}
                                    <button onClick={() => removeCible(c.id)} disabled={removingCibleId === c.id} title="Retirer cette cible"
                                      style={{ background: "none", border: "none", padding: 1, display: "flex" }}>
                                      <X size={10} color={C.mutedSoft} />
                                    </button>
                                  </span>
                                );
                              })}
                            </div>
                          </div>
                          <div className="flex items-center gap-2" style={{ flexShrink: 0 }}>
                            <span style={{ fontSize: 11, color: C.mutedSoft, fontFamily: "'IBM Plex Mono', monospace" }}>
                              {nbFiches === undefined ? "…" : nbFiches === null ? "—" : `${nbFiches} fiche${nbFiches !== 1 ? "s" : ""}`}
                            </span>
                            {!confirming && !addingCible && (
                              <>
                                <button onClick={() => startAddCible(l)} title="Ajouter une cible (agent/groupe)"
                                  style={{ background: "none", border: "none", padding: 4 }}>
                                  <Plus size={13} color={C.mutedSoft} />
                                </button>
                                <button onClick={() => setConfirmDeleteLotId(l.id)} title="Supprimer ce lot et ses fiches"
                                  style={{ background: "none", border: "none", padding: 4 }}>
                                  <Trash2 size={13} color={C.mutedSoft} />
                                </button>
                              </>
                            )}
                          </div>
                        </div>
                        {addingCible && (
                          <div style={{ marginTop: 10, paddingTop: 10, borderTop: `1px dashed ${C.border}` }}>
                            <div className="flex items-center gap-2 mb-2">
                              <div style={{ background: C.surface, borderRadius: 7, padding: 3, border: `1px solid ${C.border}` }} className="flex gap-1">
                                {[{ id: "agent", label: "Agent" }, { id: "groupe", label: "Groupe" }].map((t) => (
                                  <button key={t.id} onClick={() => { setNewCibleType(t.id); setNewCibleId(""); }}
                                    style={{ padding: "5px 11px", borderRadius: 5, border: "none", background: newCibleType === t.id ? C.ink : "transparent", color: newCibleType === t.id ? "#fff" : C.muted, fontSize: 11.5, fontWeight: 600 }}>
                                    {t.label}
                                  </button>
                                ))}
                              </div>
                              <select value={newCibleId} onChange={(e) => setNewCibleId(e.target.value)}
                                style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "6px 9px", fontSize: 12, background: C.surface }}>
                                <option value="">Choisir {newCibleType === "agent" ? "un agent" : "un groupe"}…</option>
                                {newCibleOptions.map((o) => <option key={o.id} value={o.id}>{o.nom}</option>)}
                              </select>
                            </div>
                            <div className="flex items-center gap-2">
                              <button onClick={() => addCible(l.id)} disabled={savingCible || !newCibleId}
                                style={{ background: C.amber, color: C.ink, border: "none", borderRadius: 6, padding: "6px 12px", fontSize: 11.5, fontWeight: 700, display: "flex", alignItems: "center", gap: 5 }}>
                                {savingCible && <Loader2 size={11} className="animate-spin" />} Ajouter
                              </button>
                              <button onClick={() => setAddingCibleLotId(null)} style={{ background: "none", border: "none", color: C.muted, fontSize: 11.5 }}>
                                Annuler
                              </button>
                            </div>
                            <p style={{ fontSize: 10.5, color: C.mutedSoft, marginTop: 6 }}>
                              S'ajoute aux cibles déjà en place — rien n'est retiré ni réimporté.
                            </p>
                          </div>
                        )}
                        {confirming && (
                          <div className="flex items-center justify-between mt-2" style={{ paddingTop: 8, borderTop: `1px dashed ${C.red}` }}>
                            <span style={{ fontSize: 11, color: C.red, fontWeight: 500 }}>
                              Supprimer définitivement ce lot et ses {nbFiches ?? "?"} fiche(s) ?
                            </span>
                            <div className="flex items-center gap-2">
                              <button onClick={() => deleteLot(l.id)} disabled={deletingLotId === l.id}
                                style={{ background: C.red, color: "#fff", border: "none", borderRadius: 6, padding: "5px 10px", fontSize: 11.5, fontWeight: 600, display: "flex", alignItems: "center", gap: 5 }}>
                                {deletingLotId === l.id && <Loader2 size={11} className="animate-spin" />} Confirmer
                              </button>
                              <button onClick={() => setConfirmDeleteLotId(null)} style={{ background: "none", border: "none", color: C.muted, fontSize: 11.5 }}>
                                Annuler
                              </button>
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function GroupesTab({ accessToken, groupes, agents, membres, selected, setSelected, reload }) {
  const [showNew, setShowNew] = useState(false);
  const [nom, setNom] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);

  async function createGroupe() {
    if (!nom.trim()) return;
    setBusy(true); setError(null);
    try {
      await supaRest("groupes_agents", { method: "POST", accessToken, body: { nom: nom.trim() } });
      setNom(""); setShowNew(false);
      reload();
    } catch (e) { setError(e.message); } finally { setBusy(false); }
  }

  async function toggleMembre(groupeId, agentId, isMember) {
    try {
      if (isMember) {
        await supaRest(`groupes_agents_membres?groupe_id=eq.${groupeId}&agent_id=eq.${agentId}`, { method: "DELETE", accessToken });
      } else {
        await supaRest("groupes_agents_membres", { method: "POST", accessToken, body: { groupe_id: groupeId, agent_id: agentId } });
      }
      reload();
    } catch (e) { setError(e.message); }
  }

  const current = groupes.find((g) => g.id === selected) || null;

  return (
    <div style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: 20 }}>
      <div>
        <button onClick={() => setShowNew((v) => !v)}
          style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, background: C.ink, color: "#fff", border: "none", borderRadius: 9, padding: "10px 0", fontSize: 13, fontWeight: 600, marginBottom: 12 }}>
          <Plus size={14} /> Nouveau groupe d'agents
        </button>

        {showNew && (
          <div style={{ background: C.surface, border: `1.5px solid ${C.ink}`, borderRadius: 10, padding: 12, marginBottom: 12 }}>
            <input value={nom} onChange={(e) => setNom(e.target.value)} placeholder="Nom du groupe…" autoFocus
              style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, marginBottom: 8 }} />
            <button onClick={createGroupe} disabled={busy}
              style={{ width: "100%", background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "8px 0", fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
              {busy && <Loader2 size={12} className="animate-spin" />} Créer
            </button>
          </div>
        )}

        {error && <div className="mb-3"><ErrorBlock message={error} /></div>}

        <div className="flex flex-col gap-2">
          {groupes.length === 0 && <p style={{ fontSize: 12.5, color: C.muted }}>Aucun groupe créé.</p>}
          {groupes.map((g) => {
            const nbMembres = membres.filter((m) => m.groupe_id === g.id).length;
            const isActive = selected === g.id;
            return (
              <button key={g.id} onClick={() => setSelected(g.id)}
                style={{ textAlign: "left", background: isActive ? C.ink : C.surface, color: isActive ? "#fff" : C.text, border: `1px solid ${isActive ? C.ink : C.border}`, borderRadius: 10, padding: "12px 14px" }}>
                <div style={{ fontSize: 13, fontWeight: 600 }}>{g.nom}</div>
                <div style={{ fontSize: 11, color: isActive ? "#A6ADBA" : C.muted, marginTop: 2 }}>
                  {nbMembres} agent{nbMembres !== 1 ? "s" : ""}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div>
        {!current ? (
          <div style={{ background: C.surface, border: `1px dashed ${C.border}`, borderRadius: 12, padding: 40, textAlign: "center", color: C.muted, fontSize: 13 }}>
            Sélectionnez un groupe pour gérer ses membres.
          </div>
        ) : (
          <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 20 }}>
            <h3 className="disp" style={{ fontSize: 16, fontWeight: 700 }}>{current.nom}</h3>
            <p style={{ fontSize: 12.5, color: C.muted, marginTop: 3 }}>Cochez les agents membres de ce groupe.</p>

            <div className="flex flex-wrap gap-2" style={{ marginTop: 16 }}>
              {agents.length === 0 ? (
                <p style={{ fontSize: 12, color: C.mutedSoft }}>Aucun agent enregistré.</p>
              ) : agents.map((ag) => {
                const isMember = membres.some((m) => m.groupe_id === current.id && m.agent_id === ag.id);
                return (
                  <button key={ag.id} onClick={() => toggleMembre(current.id, ag.id, isMember)}
                    style={{ display: "flex", alignItems: "center", gap: 6, border: `1.5px solid ${isMember ? C.teal : C.border}`, background: isMember ? C.tealSoft : C.surface, color: isMember ? C.teal : C.text, borderRadius: 999, padding: "7px 13px", fontSize: 12.5, fontWeight: 500 }}>
                    {isMember ? <Check size={13} /> : <Plus size={13} />} {ag.nom}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}


/* ---------------------------------- super admin : équipes ---------------------------------- */

function EquipesPanel({ accessToken }) {
  const [equipes, setEquipes] = useState(null);
  const [coachs, setCoachs] = useState(null);
  const [agents, setAgents] = useState(null);
  const [error, setError] = useState(null);
  const [selected, setSelected] = useState(null);

  const [showNew, setShowNew] = useState(false);
  const [nomNouvelle, setNomNouvelle] = useState("");
  const [creating, setCreating] = useState(false);

  const [editingNom, setEditingNom] = useState(false);
  const [editNomValue, setEditNomValue] = useState("");
  const [savingNom, setSavingNom] = useState(false);

  const [assigningCoach, setAssigningCoach] = useState(false);
  const [savingCoach, setSavingCoach] = useState(false);

  const load = useCallback(async () => {
    try {
      const [eq, co, ag] = await Promise.all([
        supaRest("equipes?select=*&order=created_at.desc", { accessToken }),
        supaRest("profils?select=id,nom&role=eq.coach&order=nom.asc", { accessToken }),
        supaRest("profils?select=id,nom,equipe_id&role=eq.agent&order=nom.asc", { accessToken }),
      ]);
      setEquipes(eq); setCoachs(co); setAgents(ag);
    } catch (e) { setError(e.message); }
  }, [accessToken]);

  useEffect(() => { load(); }, [load]);

  async function createEquipe() {
    if (!nomNouvelle.trim()) return;
    setCreating(true); setError(null);
    try {
      await rpc("super_admin_creer_equipe", accessToken, { p_nom: nomNouvelle.trim() });
      setNomNouvelle(""); setShowNew(false);
      load();
    } catch (e) { setError(e.message); } finally { setCreating(false); }
  }

  async function renommerEquipe(id) {
    if (!editNomValue.trim()) return;
    setSavingNom(true); setError(null);
    try {
      await rpc("super_admin_renommer_equipe", accessToken, { p_equipe_id: id, p_nom: editNomValue.trim() });
      setEditingNom(false);
      load();
    } catch (e) { setError(e.message); } finally { setSavingNom(false); }
  }

  async function assignerCoach(equipeId, coachId) {
    setSavingCoach(true); setError(null);
    try {
      await rpc("super_admin_assigner_coach_equipe", accessToken, { p_equipe_id: equipeId, p_coach_id: coachId || null });
      setAssigningCoach(false);
      load();
    } catch (e) { setError(e.message); } finally { setSavingCoach(false); }
  }

  async function rattacherAgent(agentId, equipeId) {
    setError(null);
    try {
      await rpc("super_admin_rattacher", accessToken, { p_profil_id: agentId, p_champ: "equipe_id", p_cible_id: equipeId || null });
      load();
    } catch (e) { setError(e.message); }
  }

  const current = equipes?.find((e) => e.id === selected) || null;
  const agentsDeLequipe = current ? (agents || []).filter((a) => a.equipe_id === current.id) : [];
  const agentsSansEquipe = (agents || []).filter((a) => !a.equipe_id);

  if (!equipes || !coachs || !agents) return <CenterLoader />;

  return (
    <div>
      <header className="mb-6">
        <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Équipes</h1>
        <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>
          Chaque équipe regroupe des agents et est rattachée à un coach. Renommer une équipe n'affecte pas ses agents.
        </p>
      </header>

      {error && <div className="mb-4"><ErrorBlock message={error} /></div>}

      <div style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: 20 }}>
        <div>
          <button onClick={() => setShowNew((v) => !v)}
            style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, background: C.ink, color: "#fff", border: "none", borderRadius: 9, padding: "10px 0", fontSize: 13, fontWeight: 600, marginBottom: 12 }}>
            <Plus size={14} /> Nouvelle équipe
          </button>

          {showNew && (
            <div style={{ background: C.surface, border: `1.5px solid ${C.ink}`, borderRadius: 10, padding: 12, marginBottom: 12 }}>
              <input value={nomNouvelle} onChange={(e) => setNomNouvelle(e.target.value)} placeholder="Nom de l'équipe…" autoFocus
                style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, marginBottom: 8 }} />
              <button onClick={createEquipe} disabled={creating}
                style={{ width: "100%", background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "8px 0", fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                {creating && <Loader2 size={12} className="animate-spin" />} Créer
              </button>
            </div>
          )}

          <div className="flex flex-col gap-2">
            {equipes.length === 0 && <p style={{ fontSize: 12.5, color: C.muted }}>Aucune équipe créée.</p>}
            {equipes.map((eq) => {
              const nbAgents = agents.filter((a) => a.equipe_id === eq.id).length;
              const coachNom = coachs.find((c) => c.id === eq.coach_id)?.nom;
              const isActive = selected === eq.id;
              return (
                <button key={eq.id} onClick={() => { setSelected(eq.id); setEditingNom(false); setAssigningCoach(false); }}
                  style={{ textAlign: "left", background: isActive ? C.ink : C.surface, color: isActive ? "#fff" : C.text, border: `1px solid ${isActive ? C.ink : C.border}`, borderRadius: 10, padding: "12px 14px" }}>
                  <div style={{ fontSize: 13, fontWeight: 600 }}>{eq.nom}</div>
                  <div style={{ fontSize: 11, color: isActive ? "#A6ADBA" : C.muted, marginTop: 2 }}>
                    {nbAgents} agent{nbAgents !== 1 ? "s" : ""} · {coachNom || "sans coach"}
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div>
          {!current ? (
            <div style={{ background: C.surface, border: `1px dashed ${C.border}`, borderRadius: 12, padding: 40, textAlign: "center", color: C.muted, fontSize: 13 }}>
              Sélectionnez une équipe pour la gérer.
            </div>
          ) : (
            <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 20 }}>
              <div className="flex items-center gap-2">
                {!editingNom ? (
                  <>
                    <h3 className="disp" style={{ fontSize: 16, fontWeight: 700 }}>{current.nom}</h3>
                    <button onClick={() => { setEditingNom(true); setEditNomValue(current.nom); }} title="Renommer"
                      style={{ background: "none", border: "none", padding: 2 }}>
                      <ListChecks size={13} color={C.mutedSoft} />
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2" style={{ flex: 1 }}>
                    <input value={editNomValue} onChange={(e) => setEditNomValue(e.target.value)} autoFocus
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "6px 9px", fontSize: 13.5, fontWeight: 600 }} />
                    <button onClick={() => renommerEquipe(current.id)} disabled={savingNom}
                      style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 7, padding: "6px 10px" }}>
                      {savingNom ? <Loader2 size={12} className="animate-spin" /> : <Check size={12} />}
                    </button>
                    <button onClick={() => setEditingNom(false)} style={{ background: "none", border: "none", color: C.mutedSoft, padding: 4 }}>
                      <X size={14} />
                    </button>
                  </div>
                )}
              </div>
              <p style={{ fontSize: 11, color: C.mutedSoft, marginTop: 4 }}>
                Renommer une équipe n'a aucun effet sur ses agents : le rattachement repose sur l'identifiant, pas sur le nom.
              </p>

              <div style={{ marginTop: 20, paddingTop: 16, borderTop: `1px dashed ${C.border}` }}>
                <div className="flex items-center gap-1.5 mb-2" style={{ fontSize: 11.5, fontWeight: 600, color: C.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}>
                  <UserCircle2 size={13} /> Coach responsable
                </div>
                {!assigningCoach ? (
                  <div className="flex items-center gap-2">
                    <span style={{ fontSize: 13 }}>{coachs.find((c) => c.id === current.coach_id)?.nom || "Aucun coach assigné"}</span>
                    <button onClick={() => setAssigningCoach(true)} style={{ background: C.canvas, border: `1px solid ${C.border}`, borderRadius: 6, padding: "4px 9px", fontSize: 11.5, color: C.text }}>
                      Modifier
                    </button>
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <select defaultValue={current.coach_id || ""} onChange={(e) => assignerCoach(current.id, e.target.value)} disabled={savingCoach}
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, background: C.surface, maxWidth: 260 }}>
                      <option value="">Aucun coach</option>
                      {coachs.map((c) => <option key={c.id} value={c.id}>{c.nom}</option>)}
                    </select>
                    <button onClick={() => setAssigningCoach(false)} style={{ background: "none", border: "none", color: C.mutedSoft, fontSize: 11.5 }}>Fermer</button>
                  </div>
                )}
              </div>

              <div style={{ marginTop: 20, paddingTop: 16, borderTop: `1px dashed ${C.border}` }}>
                <div className="flex items-center gap-1.5 mb-2" style={{ fontSize: 11.5, fontWeight: 600, color: C.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}>
                  <Users size={13} /> Agents de l'équipe ({agentsDeLequipe.length})
                </div>
                {agentsDeLequipe.length === 0 ? (
                  <p style={{ fontSize: 12.5, color: C.mutedSoft, marginBottom: 10 }}>Aucun agent dans cette équipe pour le moment.</p>
                ) : (
                  <div className="flex flex-wrap gap-2 mb-3">
                    {agentsDeLequipe.map((a) => (
                      <span key={a.id} className="flex items-center gap-2" style={{ background: C.canvas, borderRadius: 999, padding: "6px 6px 6px 12px", fontSize: 12.5 }}>
                        {a.nom}
                        <button onClick={() => rattacherAgent(a.id, null)} title="Retirer de l'équipe" style={{ background: "none", border: "none", padding: 3 }}>
                          <X size={11} color={C.mutedSoft} />
                        </button>
                      </span>
                    ))}
                  </div>
                )}

                {agentsSansEquipe.length > 0 && (
                  <div className="flex items-center gap-2">
                    <select defaultValue="" onChange={(e) => { if (e.target.value) { rattacherAgent(e.target.value, current.id); e.target.value = ""; } }}
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 9px", fontSize: 12.5, background: C.surface, maxWidth: 260 }}>
                      <option value="">+ Ajouter un agent sans équipe…</option>
                      {agentsSansEquipe.map((a) => <option key={a.id} value={a.id}>{a.nom}</option>)}
                    </select>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------- admin : utilisateurs (création de comptes) ---------------------------------- */

function UsersPanel({ accessToken, isSuperAdmin }) {
  const [comptes, setComptes] = useState(null);
  const [roleFiltre, setRoleFiltre] = useState("tous");
  const [error, setError] = useState(null);
  const [nom, setNom] = useState("");
  const [login, setLogin] = useState("");
  const [roleChoisi, setRoleChoisi] = useState("agent");
  const [creating, setCreating] = useState(false);
  const [lastCreated, setLastCreated] = useState(null); // { login, mot_de_passe, matricule }

  const [editingId, setEditingId] = useState(null);
  const [editNom, setEditNom] = useState("");
  const [editLogin, setEditLogin] = useState("");
  const [savingEdit, setSavingEdit] = useState(false);

  const [resettingId, setResettingId] = useState(null);
  const [lastReset, setLastReset] = useState(null); // { compte, mot_de_passe }

  const [managingPermsId, setManagingPermsId] = useState(null);
  const [permsEnCours, setPermsEnCours] = useState({ effective: new Set(), overrides: {} });
  const [permsBusy, setPermsBusy] = useState(false);

  const [superviseursDispo, setSuperviseursDispo] = useState([]);
  const [adminsDispo, setAdminsDispo] = useState([]);
  const [rattachBusy, setRattachBusy] = useState(false);

  useEffect(() => {
    if (!isSuperAdmin) return;
    (async () => {
      try {
        const [sups, adms] = await Promise.all([
          supaRest("profils?select=id,nom&role=eq.superviseur&order=nom.asc", { accessToken }),
          supaRest("profils?select=id,nom&role=in.(admin,super_admin)&order=nom.asc", { accessToken }),
        ]);
        setSuperviseursDispo(sups); setAdminsDispo(adms);
      } catch {}
    })();
  }, [accessToken, isSuperAdmin]);

  const load = useCallback(async () => {
    try {
      const rows = await supaRest("profils?select=id,nom,login,role,statut,matricule,actif,superviseur_id,admin_id&role=in.(agent,superviseur,coach,admin)&order=nom.asc", { accessToken });
      setComptes(rows);
    } catch (e) { setError(e.message); }
  }, [accessToken]);

  useEffect(() => { load(); }, [load]);

  async function createCompte(e) {
    e.preventDefault();
    if (!nom.trim() || !login.trim()) return;
    setCreating(true); setError(null); setLastCreated(null);
    try {
      const result = await rpc("admin_create_compte", accessToken, { p_nom: nom.trim(), p_login: login.trim(), p_role: roleChoisi });
      const row = Array.isArray(result) ? result[0] : result;
      setLastCreated(row);
      setNom(""); setLogin("");
      load();
    } catch (e) { setError(e.message); } finally { setCreating(false); }
  }

  function startEdit(c) {
    setEditingId(c.id); setEditNom(c.nom); setEditLogin(c.login || "");
    setLastReset(null); setManagingPermsId(null);
  }

  async function saveEdit(id) {
    setSavingEdit(true); setError(null);
    try {
      await rpc("admin_update_profil", accessToken, { p_profil_id: id, p_nom: editNom.trim(), p_login: editLogin.trim(), p_actif: null });
      setEditingId(null);
      load();
    } catch (e) { setError(e.message); } finally { setSavingEdit(false); }
  }

  async function toggleActif(c) {
    setError(null);
    try {
      await rpc("admin_update_profil", accessToken, { p_profil_id: c.id, p_nom: null, p_login: null, p_actif: !c.actif });
      load();
    } catch (e) { setError(e.message); }
  }

  async function resetPassword(c) {
    setResettingId(c.id); setError(null); setLastReset(null);
    try {
      const newPassword = await rpc("admin_reset_password", accessToken, { p_profil_id: c.id });
      setLastReset({ compte: c, mot_de_passe: newPassword });
    } catch (e) { setError(e.message); } finally { setResettingId(null); }
  }

  async function openPerms(c) {
    setManagingPermsId(c.id); setEditingId(null); setError(null);
    try {
      const rows = await supaRest(`permissions_personnalisees?select=ecran,autorise&profil_id=eq.${c.id}`, { accessToken });
      const effective = new Set(ROLE_DEFAULT_TABS[c.role] || []);
      const overrides = {};
      rows.forEach((r) => { overrides[r.ecran] = r.autorise; if (r.autorise) effective.add(r.ecran); else effective.delete(r.ecran); });
      setPermsEnCours({ effective, overrides });
    } catch (e) { setError(e.message); }
  }

  async function togglePerm(profilId, ecran, autorise) {
    setPermsBusy(true); setError(null);
    try {
      await rpc("super_admin_set_permission", accessToken, { p_profil_id: profilId, p_ecran: ecran, p_autorise: autorise });
      setPermsEnCours((prev) => {
        const effective = new Set(prev.effective);
        autorise ? effective.add(ecran) : effective.delete(ecran);
        return { effective, overrides: { ...prev.overrides, [ecran]: autorise } };
      });
    } catch (e) { setError(e.message); } finally { setPermsBusy(false); }
  }

  async function resetPerm(cible, ecran) {
    setPermsBusy(true); setError(null);
    try {
      await rpc("super_admin_reset_permission", accessToken, { p_profil_id: cible.id, p_ecran: ecran });
      setPermsEnCours((prev) => {
        const effective = new Set(prev.effective);
        const parDefaut = (ROLE_DEFAULT_TABS[cible.role] || []).includes(ecran);
        parDefaut ? effective.add(ecran) : effective.delete(ecran);
        const overrides = { ...prev.overrides };
        delete overrides[ecran];
        return { effective, overrides };
      });
    } catch (e) { setError(e.message); } finally { setPermsBusy(false); }
  }

  async function rattacherHierarchie(cible, champ, cibleId) {
    setRattachBusy(true); setError(null);
    try {
      await rpc("super_admin_rattacher", accessToken, { p_profil_id: cible.id, p_champ: champ, p_cible_id: cibleId || null });
      load();
    } catch (e) { setError(e.message); } finally { setRattachBusy(false); }
  }

  const roleOptions = isSuperAdmin
    ? [{ id: "agent", label: "Agent" }, { id: "superviseur", label: "Superviseur" }, { id: "coach", label: "Coach" }, { id: "admin", label: "Admin" }]
    : [{ id: "agent", label: "Agent" }, { id: "superviseur", label: "Superviseur" }, { id: "coach", label: "Coach" }];

  return (
    <div>
      <header className="mb-6">
        <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Utilisateurs</h1>
        <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Crée un accès Supabase réel (login + mot de passe généré) pour un agent, un superviseur, un coach{isSuperAdmin ? " ou un administrateur" : ""}.</p>
      </header>

      <form onSubmit={createCompte} style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18, marginBottom: 20, maxWidth: 620 }}>
        <div className="flex items-center gap-2 mb-3">
          <div style={{ background: C.canvas, borderRadius: 8, padding: 3 }} className="flex gap-1">
            {roleOptions.map((r) => (
              <button key={r.id} type="button" onClick={() => setRoleChoisi(r.id)}
                style={{ padding: "7px 14px", borderRadius: 6, border: "none", background: roleChoisi === r.id ? C.ink : "transparent", color: roleChoisi === r.id ? "#fff" : C.muted, fontSize: 12.5, fontWeight: 600 }}>
                {r.label}
              </button>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <input value={nom} onChange={(e) => setNom(e.target.value)} placeholder="Nom complet…"
            style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "9px 11px", fontSize: 13 }} />
          <input value={login} onChange={(e) => setLogin(e.target.value)} placeholder="Login…"
            style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "9px 11px", fontSize: 13 }} />
          <button type="submit" disabled={creating}
            style={{ background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "9px 16px", fontSize: 13, fontWeight: 700, display: "flex", alignItems: "center", gap: 6, whiteSpace: "nowrap" }}>
            {creating && <Loader2 size={13} className="animate-spin" />} Créer le compte
          </button>
        </div>
      </form>

      {lastCreated && (
        <div style={{ background: C.greenSoft, border: `1px solid ${C.green}`, borderRadius: 10, padding: 16, marginBottom: 20, maxWidth: 620 }}>
          <div className="flex items-center gap-2" style={{ color: C.green, fontWeight: 600, fontSize: 13, marginBottom: 8 }}>
            <CheckCircle2 size={15} /> Compte créé — communique ces identifiants, ils ne seront plus affichés.
          </div>
          <div className="flex items-center gap-6">
            <div>
              <div style={{ fontSize: 10.5, color: C.muted, textTransform: "uppercase" }}>Matricule</div>
              <div className="mono" style={{ fontSize: 14, fontWeight: 600 }}>{lastCreated.matricule}</div>
            </div>
            <div>
              <div style={{ fontSize: 10.5, color: C.muted, textTransform: "uppercase" }}>Login</div>
              <div className="mono" style={{ fontSize: 14, fontWeight: 600 }}>{lastCreated.login}</div>
            </div>
            <div>
              <div style={{ fontSize: 10.5, color: C.muted, textTransform: "uppercase" }}>Mot de passe</div>
              <div className="mono" style={{ fontSize: 14, fontWeight: 600 }}>{lastCreated.mot_de_passe}</div>
            </div>
          </div>
        </div>
      )}

      {lastReset && (
        <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: 16, marginBottom: 20, maxWidth: 620 }}>
          <div className="flex items-center gap-2" style={{ color: "#8a5c14", fontWeight: 600, fontSize: 13, marginBottom: 8 }}>
            <RotateCcw size={15} /> Mot de passe réinitialisé pour {lastReset.compte.nom} — communique-le, il ne sera plus affiché.
          </div>
          <div className="flex items-center gap-6">
            <div>
              <div style={{ fontSize: 10.5, color: C.muted, textTransform: "uppercase" }}>Login</div>
              <div className="mono" style={{ fontSize: 14, fontWeight: 600 }}>{lastReset.compte.login}</div>
            </div>
            <div>
              <div style={{ fontSize: 10.5, color: C.muted, textTransform: "uppercase" }}>Nouveau mot de passe</div>
              <div className="mono" style={{ fontSize: 14, fontWeight: 600 }}>{lastReset.mot_de_passe}</div>
            </div>
          </div>
        </div>
      )}

      {error && <div className="mb-4"><ErrorBlock message={error} /></div>}

      {comptes === null ? (
        <CenterLoader />
      ) : (() => {
        const filtres = [
          { id: "tous", label: "Tous" },
          { id: "agent", label: "Agents" },
          { id: "superviseur", label: "Superviseurs" },
          { id: "coach", label: "Coachs" },
          ...(isSuperAdmin ? [{ id: "admin", label: "Admins" }] : []),
        ];
        const comptesFiltres = roleFiltre === "tous" ? comptes : comptes.filter((c) => c.role === roleFiltre);
        return (
        <>
        <div className="flex items-center gap-1 mb-3" style={{ background: C.canvas, borderRadius: 9, padding: 3, width: "fit-content" }}>
          {filtres.map((f) => {
            const count = f.id === "tous" ? comptes.length : comptes.filter((c) => c.role === f.id).length;
            return (
              <button key={f.id} onClick={() => setRoleFiltre(f.id)}
                style={{ padding: "6px 13px", borderRadius: 6, border: "none", background: roleFiltre === f.id ? C.ink : "transparent", color: roleFiltre === f.id ? "#fff" : C.muted, fontSize: 12, fontWeight: 600 }}>
                {f.label} <span style={{ opacity: 0.7 }}>({count})</span>
              </button>
            );
          })}
        </div>
        <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, overflow: "hidden", maxWidth: 900 }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
            <thead>
              <tr style={{ background: C.canvas, textAlign: "left" }}>
                {["Matricule", "Nom", "Login", "Rôle", "Statut", ""].map((h) => (
                  <th key={h} style={{ padding: "10px 16px", color: C.muted, fontWeight: 600, fontSize: 11, textTransform: "uppercase" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {comptesFiltres.length === 0 ? (
                <tr><td colSpan={6} style={{ padding: "20px 16px", textAlign: "center", color: C.mutedSoft, fontSize: 12.5 }}>Aucun compte pour ce rôle.</td></tr>
              ) : comptesFiltres.map((c) => (
                <tr key={c.id} style={{ borderTop: `1px solid ${C.borderSoft}`, opacity: c.actif === false ? 0.55 : 1 }}>
                  <td className="mono" style={{ padding: "10px 16px", color: C.mutedSoft }}>{c.matricule}</td>
                  {editingId === c.id ? (
                    <>
                      <td style={{ padding: "8px 16px" }}>
                        <input value={editNom} onChange={(e) => setEditNom(e.target.value)}
                          style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 6, padding: "5px 8px", fontSize: 12.5 }} />
                      </td>
                      <td style={{ padding: "8px 16px" }}>
                        <input value={editLogin} onChange={(e) => setEditLogin(e.target.value)}
                          className="mono" style={{ width: "100%", border: `1px solid ${C.border}`, borderRadius: 6, padding: "5px 8px", fontSize: 12.5 }} />
                      </td>
                      <td style={{ padding: "10px 16px", textTransform: "capitalize" }}>{c.role}</td>
                      <td style={{ padding: "10px 16px" }}>
                        <span style={{ background: C.borderSoft, color: C.muted, padding: "2px 9px", borderRadius: 999, fontSize: 11, fontWeight: 600 }}>
                          {AGENT_STATUTS.find((s) => s.id === c.statut)?.label || c.statut}
                        </span>
                      </td>
                      <td style={{ padding: "10px 16px" }}>
                        <div className="flex items-center gap-1">
                          <button onClick={() => saveEdit(c.id)} disabled={savingEdit} title="Enregistrer"
                            style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 6, padding: 6 }}>
                            {savingEdit ? <Loader2 size={12} className="animate-spin" /> : <Check size={12} />}
                          </button>
                          <button onClick={() => setEditingId(null)} title="Annuler"
                            style={{ background: "none", border: "none", color: C.mutedSoft, padding: 6 }}>
                            <X size={13} />
                          </button>
                        </div>
                      </td>
                    </>
                  ) : (
                    <>
                      <td style={{ padding: "10px 16px", fontWeight: 500 }}>{c.nom}</td>
                      <td className="mono" style={{ padding: "10px 16px", color: C.muted }}>{c.login}</td>
                      <td style={{ padding: "10px 16px", textTransform: "capitalize" }}>{c.role}</td>
                      <td style={{ padding: "10px 16px" }}>
                        <span style={{ background: c.actif === false ? C.redSoft : C.borderSoft, color: c.actif === false ? C.red : C.muted, padding: "2px 9px", borderRadius: 999, fontSize: 11, fontWeight: 600 }}>
                          {c.actif === false ? "Désactivé" : (AGENT_STATUTS.find((s) => s.id === c.statut)?.label || c.statut)}
                        </span>
                      </td>
                      <td style={{ padding: "10px 16px" }}>
                        <div className="flex items-center gap-1">
                          <button onClick={() => startEdit(c)} title="Modifier"
                            style={{ background: "none", border: "none", padding: 5 }}>
                            <ListChecks size={13} color={C.mutedSoft} />
                          </button>
                          <button onClick={() => resetPassword(c)} disabled={resettingId === c.id} title="Réinitialiser le mot de passe"
                            style={{ background: "none", border: "none", padding: 5 }}>
                            {resettingId === c.id ? <Loader2 size={13} className="animate-spin" color={C.mutedSoft} /> : <RotateCcw size={13} color={C.mutedSoft} />}
                          </button>
                          <button onClick={() => toggleActif(c)} title={c.actif === false ? "Réactiver" : "Désactiver"}
                            style={{ background: "none", border: "none", padding: 5 }}>
                            {c.actif === false ? <PlayCircle size={13} color={C.green} /> : <PowerOff size={13} color={C.red} />}
                          </button>
                          {isSuperAdmin && ["admin", "superviseur", "coach"].includes(c.role) && (
                            <button onClick={() => openPerms(c)} title="Gérer les accès supplémentaires"
                              style={{ background: "none", border: "none", padding: 5 }}>
                              <Key size={13} color={C.mutedSoft} />
                            </button>
                          )}
                        </div>
                      </td>
                    </>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        </>
        );
      })()}

      {managingPermsId && (() => {
        const cible = comptes.find((c) => c.id === managingPermsId);
        if (!cible) return null;
        const roleLabel = { admin: "Admin", superviseur: "Superviseur", coach: "Coach" }[cible.role] || cible.role;
        return (
          <div style={{ background: C.surface, border: `1.5px solid ${C.ink}`, borderRadius: 12, padding: 18, marginTop: 20, maxWidth: 620 }}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Key size={14} color={C.muted} />
                <h3 className="disp" style={{ fontSize: 14, fontWeight: 700 }}>Accès personnalisés — {cible.nom} <span style={{ color: C.mutedSoft, fontWeight: 400 }}>({roleLabel})</span></h3>
              </div>
              <button onClick={() => setManagingPermsId(null)} style={{ background: "none", border: "none", color: C.mutedSoft, padding: 4 }}><X size={15} /></button>
            </div>
            <p style={{ fontSize: 11.5, color: C.mutedSoft, marginBottom: 12 }}>
              Coche pour donner accès, décoche pour retirer — même un écran normalement inclus par défaut dans le rôle {roleLabel}. Un repère apparaît sur les écrans qui dérogent au réglage par défaut du rôle.
            </p>
            <div className="flex flex-col gap-2">
              {TAB_DEFS.map((e) => {
                const accorde = permsEnCours.effective.has(e.id);
                const parDefaut = (ROLE_DEFAULT_TABS[cible.role] || []).includes(e.id);
                const derogation = permsEnCours.overrides[e.id] !== undefined;
                return (
                  <div key={e.id} className="flex items-center justify-between">
                    <label className="flex items-center gap-2" style={{ fontSize: 13, cursor: "pointer" }}>
                      <input type="checkbox" checked={accorde} disabled={permsBusy}
                        onChange={(ev) => togglePerm(cible.id, e.id, ev.target.checked)} />
                      {e.label}
                      {derogation && (
                        <span style={{ fontSize: 10, color: accorde ? C.green : C.red, background: accorde ? C.greenSoft : C.redSoft, padding: "1px 7px", borderRadius: 999, fontWeight: 600 }}>
                          {accorde ? "ajouté" : "retiré"}
                        </span>
                      )}
                      {!derogation && !parDefaut && (
                        <span style={{ fontSize: 10, color: C.mutedSoft }}>(hors rôle)</span>
                      )}
                    </label>
                    {derogation && (
                      <button onClick={() => resetPerm(cible, e.id)} disabled={permsBusy} title="Revenir au réglage par défaut du rôle"
                        style={{ background: "none", border: "none", color: C.mutedSoft, fontSize: 11 }}>
                        <RotateCcw size={12} />
                      </button>
                    )}
                  </div>
                );
              })}
            </div>

            {(cible.role === "coach" || cible.role === "superviseur") && (
              <div style={{ marginTop: 18, paddingTop: 16, borderTop: `1px dashed ${C.border}` }}>
                <div className="flex items-center gap-1.5 mb-2" style={{ fontSize: 11.5, fontWeight: 600, color: C.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}>
                  <UsersRound size={13} /> Rattachement hiérarchique
                </div>
                {cible.role === "coach" ? (
                  <div className="flex items-center gap-2">
                    <span style={{ fontSize: 12.5, color: C.muted, whiteSpace: "nowrap" }}>Superviseur :</span>
                    <select value={cible.superviseur_id || ""} disabled={rattachBusy}
                      onChange={(ev) => rattacherHierarchie(cible, "superviseur_id", ev.target.value)}
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "6px 9px", fontSize: 12.5, background: C.surface }}>
                      <option value="">Aucun</option>
                      {superviseursDispo.map((s) => <option key={s.id} value={s.id}>{s.nom}</option>)}
                    </select>
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <span style={{ fontSize: 12.5, color: C.muted, whiteSpace: "nowrap" }}>Admin :</span>
                    <select value={cible.admin_id || ""} disabled={rattachBusy}
                      onChange={(ev) => rattacherHierarchie(cible, "admin_id", ev.target.value)}
                      style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "6px 9px", fontSize: 12.5, background: C.surface }}>
                      <option value="">Aucun</option>
                      {adminsDispo.map((a) => <option key={a.id} value={a.id}>{a.nom}</option>)}
                    </select>
                  </div>
                )}
                <p style={{ fontSize: 10.5, color: C.mutedSoft, marginTop: 6 }}>
                  Détermine les stats visibles par ce compte (et, pour un admin, la présence de ses superviseurs).
                </p>
              </div>
            )}
          </div>
        );
      })()}
    </div>
  );
}


/* ---------------------------------- admin : règles ---------------------------------- */

function Rules({ accessToken, tree, reload }) {
  const [error, setError] = useState(null);
  const [showNewCat, setShowNewCat] = useState(false);
  const [newCatName, setNewCatName] = useState("");
  const [newCatMotif, setNewCatMotif] = useState("");
  const [newCatDelay, setNewCatDelay] = useState(24);
  const [newCatTerminal, setNewCatTerminal] = useState(false);
  const [creatingCat, setCreatingCat] = useState(false);

  async function updateSub(id, patch) {
    try {
      await supaRest(`types_qualification?id=eq.${id}`, { method: "PATCH", accessToken, body: patch });
      reload();
    } catch (e) { setError(e.message); }
  }
  async function deleteSub(id) {
    try {
      await supaRest(`types_qualification?id=eq.${id}`, { method: "PATCH", accessToken, body: { actif: false } });
      reload();
    } catch (e) { setError(e.message); }
  }
  async function addSub(categorie, motif, delaiHeures, terminale, ordre, estContact = true, estVente = false) {
    if (!motif.trim()) return;
    try {
      await supaRest("types_qualification", { method: "POST", accessToken, body: { categorie, motif, terminale, delai_heures: terminale ? 0 : delaiHeures, ordre, est_contact: estContact, est_vente: estVente } });
      reload();
    } catch (e) { setError(e.message); }
  }

  async function createCategory() {
    const nom = newCatName.trim();
    if (!nom || !newCatMotif.trim()) return;
    if (tree.some((c) => c.categorie.toLowerCase() === nom.toLowerCase())) {
      setError("Cette catégorie existe déjà.");
      return;
    }
    setCreatingCat(true); setError(null);
    try {
      await supaRest("types_qualification", {
        method: "POST", accessToken,
        body: { categorie: nom, motif: newCatMotif.trim(), terminale: newCatTerminal, delai_heures: newCatTerminal ? 0 : newCatDelay, ordre: 1 },
      });
      setShowNewCat(false); setNewCatName(""); setNewCatMotif(""); setNewCatDelay(24); setNewCatTerminal(false);
      reload();
    } catch (e) { setError(e.message); } finally { setCreatingCat(false); }
  }

  return (
    <div>
      <header className="mb-7 flex items-end justify-between">
        <div>
          <h1 className="disp" style={{ fontSize: 25, fontWeight: 700 }}>Règles de qualification</h1>
          <p style={{ fontSize: 13, color: C.muted, marginTop: 3 }}>Une catégorie « terminale » archive la fiche. Sinon, elle revient dans la file après le délai indiqué (en heures).</p>
        </div>
        <button onClick={() => setShowNewCat((v) => !v)}
          style={{ display: "flex", alignItems: "center", gap: 8, background: C.ink, color: "#fff", border: "none", borderRadius: 9, padding: "10px 16px", fontSize: 13, fontWeight: 600, flexShrink: 0 }}>
          <Plus size={14} /> Nouvelle catégorie
        </button>
      </header>

      {showNewCat && (
        <div style={{ background: C.surface, border: `1.5px solid ${C.ink}`, borderRadius: 12, padding: 18, marginBottom: 20, maxWidth: 640 }}>
          <div className="flex items-center gap-2 mb-3">
            <input value={newCatName} onChange={(e) => setNewCatName(e.target.value)} placeholder="Nom de la catégorie…"
              style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 13, fontWeight: 600 }} />
          </div>
          <div className="flex items-center gap-2">
            <input value={newCatMotif} onChange={(e) => setNewCatMotif(e.target.value)} placeholder="Premier motif de cette catégorie…"
              style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 10px", fontSize: 12.5 }} />
            {!newCatTerminal && (
              <input type="number" min={0} step={1} value={newCatDelay} onChange={(e) => setNewCatDelay(parseFloat(e.target.value) || 0)}
                className="mono" style={{ width: 56, border: `1px solid ${C.border}`, borderRadius: 7, padding: "8px 6px", fontSize: 12 }} />
            )}
            <label className="flex items-center gap-1" style={{ fontSize: 11, color: C.muted, whiteSpace: "nowrap" }}>
              <input type="checkbox" checked={newCatTerminal} onChange={(e) => setNewCatTerminal(e.target.checked)} /> Terminale
            </label>
            <button onClick={createCategory} disabled={creatingCat}
              style={{ background: C.amber, color: C.ink, border: "none", borderRadius: 7, padding: "8px 14px", fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", gap: 6, whiteSpace: "nowrap" }}>
              {creatingCat && <Loader2 size={12} className="animate-spin" />} Créer
            </button>
          </div>
        </div>
      )}

      {error && <div className="mb-4"><ErrorBlock message={error} /></div>}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 16 }}>
        {tree.map((cat) => (
          <RuleCard key={cat.categorie} cat={cat} onUpdate={updateSub} onDelete={deleteSub} onAdd={addSub} />
        ))}
      </div>
    </div>
  );
}

function RuleCard({ cat, onUpdate, onDelete, onAdd }) {
  const [newLabel, setNewLabel] = useState("");
  const [newDelay, setNewDelay] = useState(24);
  const [newTerminal, setNewTerminal] = useState(false);
  const [newContact, setNewContact] = useState(true);
  const [newVente, setNewVente] = useState(false);
  const Icon = cat.icon;
  const maxOrdre = Math.max(0, ...cat.subs.map((s) => s.ordre || 0));

  return (
    <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 12, padding: 18 }}>
      <div className="flex items-center gap-2 mb-4">
        <div style={{ width: 26, height: 26, borderRadius: 7, background: cat.soft }} className="flex items-center justify-center"><Icon size={14} color={cat.color} /></div>
        <span style={{ fontSize: 14, fontWeight: 600 }}>{cat.categorie}</span>
      </div>

      <div className="flex flex-col gap-2">
        {cat.subs.map((s) => (
          <div key={s.id} style={{ padding: "8px 10px", background: C.canvas, borderRadius: 8 }}>
            <div className="flex items-center gap-2">
              <span style={{ fontSize: 12.5, flex: 1, fontWeight: 500 }}>{s.motif}</span>
              <button onClick={() => onDelete(s.id)} style={{ background: "none", border: "none", padding: 2 }}><Trash2 size={13} color={C.mutedSoft} /></button>
            </div>
            <div className="flex items-center gap-2 flex-wrap mt-1.5">
              <label className="flex items-center gap-1" style={{ fontSize: 10.5, color: C.muted }}>
                <input type="checkbox" checked={s.terminale} onChange={(e) => onUpdate(s.id, { terminale: e.target.checked })} /> Terminale
              </label>
              {!s.terminale && (
                <div className="flex items-center gap-1">
                  <input type="number" min={0} step={1} value={s.delai_heures} onChange={(e) => onUpdate(s.id, { delai_heures: parseFloat(e.target.value) || 0 })}
                    className="mono" style={{ width: 44, border: `1px solid ${C.border}`, borderRadius: 6, padding: "3px 5px", fontSize: 11 }} />
                  <span style={{ fontSize: 10, color: C.mutedSoft }}>h</span>
                </div>
              )}
              <label className="flex items-center gap-1" style={{ fontSize: 10.5, color: s.est_contact ? C.teal : C.mutedSoft, fontWeight: s.est_contact ? 600 : 400 }}>
                <input type="checkbox" checked={!!s.est_contact} onChange={(e) => onUpdate(s.id, { est_contact: e.target.checked })} /> Contact
              </label>
              <label className="flex items-center gap-1" style={{ fontSize: 10.5, color: s.est_vente ? C.green : C.mutedSoft, fontWeight: s.est_vente ? 600 : 400 }}>
                <input type="checkbox" checked={!!s.est_vente} onChange={(e) => onUpdate(s.id, { est_vente: e.target.checked, ...(e.target.checked ? { est_contact: true } : {}) })} /> Vente
              </label>
            </div>
          </div>
        ))}
      </div>

      <div style={{ paddingTop: 12, marginTop: 12, borderTop: `1px dashed ${C.border}` }}>
        <div className="flex items-center gap-1.5 mb-2">
          <input value={newLabel} onChange={(e) => setNewLabel(e.target.value)} placeholder="Nouveau motif…"
            style={{ flex: 1, border: `1px solid ${C.border}`, borderRadius: 6, padding: "6px 8px", fontSize: 12 }} />
          {!newTerminal && (
            <input type="number" min={0} step={1} value={newDelay} onChange={(e) => setNewDelay(parseFloat(e.target.value) || 0)}
              className="mono" style={{ width: 46, border: `1px solid ${C.border}`, borderRadius: 6, padding: "6px 5px", fontSize: 11.5 }} />
          )}
          <button onClick={() => { onAdd(cat.categorie, newLabel, newDelay, newTerminal, maxOrdre + 1, newContact, newVente); setNewLabel(""); }}
            style={{ background: C.ink, color: "#fff", border: "none", borderRadius: 6, padding: "6px 8px" }}>
            <Plus size={13} />
          </button>
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-1" style={{ fontSize: 10.5, color: C.muted }}>
            <input type="checkbox" checked={newTerminal} onChange={(e) => setNewTerminal(e.target.checked)} /> Terminale
          </label>
          <label className="flex items-center gap-1" style={{ fontSize: 10.5, color: C.muted }}>
            <input type="checkbox" checked={newContact} onChange={(e) => setNewContact(e.target.checked)} /> Contact
          </label>
          <label className="flex items-center gap-1" style={{ fontSize: 10.5, color: C.muted }}>
            <input type="checkbox" checked={newVente} onChange={(e) => { setNewVente(e.target.checked); if (e.target.checked) setNewContact(true); }} /> Vente
          </label>
        </div>
      </div>
    </div>
  );
}
